  const attachmentPreviewUrls = new Map();
  let doc = starterDocument();

  // ---- ページ越しの参照をここに集める(複数ページ機能 Step1) ----
  // **`doc.blocks` は廃止**した。ブロックを触る処理は必ずこの3つのどれかを通す。
  // どちらを使うかは「1ページしか見なくても正しいか」で決まる:
  //   currentBlocks() … いま開いているページの配列**そのもの**。splice/push で直接書き換えてよい。
  //                     描画・編集・選択・移動など、画面の中だけで完結する処理はすべてこちら。
  //   allBlocks()     … 全ページを文書順につないだ**読み取り専用の写し**。
  //                     「どのページの内容でも見落とすとデータが消える/保存されない」処理だけが使う
  //                     (添付の掃除・埋め込みフォントの収集)。
  // **current と all を取り違えると静かにデータが消える**(例: 添付の掃除を現在ページだけで
  // 判定すると、他ページが使っている添付を「未使用」として削除する)。迷ったら all ではなく、
  // 「1ページだけ見て正しいと言い切れるか」を自問すること。
  // いま開いているページの id。**doc には入れない**(UI 状態)。
  // doc に入れると、ページを切り替えただけで JSON.stringify(doc) が変わり、saveHistory の
  // 重複排除が壊れる(切り替えが編集として履歴に積まれる)。保存ファイルへ UI 状態が漏れる経路にもなる。
  // captureCaretState() はこの id も控え、restoreCaretState() が先にそのページへ切り替えてから
  // キャレットを戻す(別ページの変更が見えないまま巻き戻るのを防ぐ)。
  let currentPageId = doc.pages[0].id;

  function currentPage() {
    // `|| doc.pages[0]` は飾りではなく**実際に効く経路**。Undo で doc が差し替わると、
    // 変数が指していたページが無くなっていることがある(Step 2: ページを作ったあとに Undo した直後など)。
    // そのとき先頭ページへ落として、画面が空にならないようにする。
    return doc.pages.find((page) => page.id === currentPageId) || doc.pages[0];
  }

  // 文書を**丸ごと**差し替える(新規作成・ファイルを開く)。差し替えても currentPageId は
  // 古い文書のページ id を指したままなので、**先頭ページへ明示的に戻す**。
  // (ページ id はファイルに保存されるので、同じファイルを開き直すと古い id が一致してしまい、
  //  フォールバックに任せると「前回見ていたページ」で開くことがある。)
  // **Undo 復元はこれを使わない**: Undo はキャレット状態の pageId からページを戻すので、
  // ここで先頭へ落とすと食い違う。Undo は doc だけを差し替える。
  // ---- 提案(v240。形式 0.8.14) ----
  // ユーザー「AIと人間がシームレスにつながって共同作業できるものにしたい」「提案のサイズを…フレキシブルに」「広い範囲で提案されているが、この一部分だけ承認したい」→ 提案(doc.suggestions)は文書の中身を変えずに持つ変更の束。人・AI・道具の誰が書いても同じ形。
  // 画面では本文の上に差分(消える所は赤の取り消し線・増える所は緑)を重ね、右のパネルに「提案 → ブロック → (表なら列) → 1か所」の
  // 木で並べる。どの段のチェックでも選べ、「選んだ所を採用 / 戻す」で一度に決める。本文の上では、表の範囲を選んで決める・語句やセル・
  // ブロックにマウスを乗せて決めることもできる。決めた結果は変更ごとに result(段落の語句ごとに決めたときは hunkResults)へ残し、
  // 提案した側が何が採られたかを読めるようにする。決めるのは1回の Undo で戻せる(doc.suggestions は Undo の控えに入る)。
  //   - 提案中の段落・セルは、決めるまで打てない(差分を見せている間は編集の場所にしない)。
  //   - 提案を書いた後に元が変わっていたら(before と今の値が違う)「古い」として採用できない(戻すだけ)。
  //   - 書式(太字・色・参照の印など)のある段落も語句ごとに決める。採用するときは書式を残したまま文字だけを当てる
  //     (applyHunksToInlineHtml。参照の印・コード・数式の途中にかかる語句は当てられない)。書き換え後の html を持つ変更だけ段落ごと。
  //   - 提案中の段落・ブロックとは、Backspace・Delete でつながない(差分を見せている中身は本文ではない。v241)。
  //   - まとめて決めるときは、文字・セル → 足す → 消す の順に、1つずつ「古くないか」を確かめてから当てる(v241)。
  const suggestUnchecked = new Set();
  const suggestExpanded = new Set();
  const suggestCollapsed = new Set();
  const suggestGhosts = new WeakMap();
  const suggestGhostChange = new WeakMap();
  let suggestPaneEl = null;
  let suggestToggleEl = null;
  let suggestPaneOpen = false;
  let suggestPopupEl = null;
  let suggestPopupTimer = 0;
  let suggestRangeBarEl = null;
  // 段落の差分の控え(変更 → 前・後の文字と差分)。描くたびに計算し直さない(v241)。
  const suggestHunkCache = new WeakMap();
  // 描き直し1回の中で使い回す控え(#205。説明は render の前)。描き直しの間だけ入っている。
  let renderMemo = null;

  function suggestionList() {
    return Array.isArray(doc.suggestions) ? doc.suggestions : [];
  }

  function findBlockAnywhere(blockId) {
    // 描き直しの間(renderMemo)は、id → 居場所の索引を1回だけ作って引く(#205)。描き直しの間はブロックが増えも減りも
    // 動きもしないが、念のため引いた居場所が今もそのブロックかを確かめ、違えば索引を作り直す。
    if (renderMemo) {
      renderMemo.blockIndex ||= buildBlockIndex();
      let hit = renderMemo.blockIndex.get(blockId);
      if (hit && !(hit.page.blocks?.[hit.index] === hit.block && hit.block.id === blockId && doc.pages.includes(hit.page))) {
        renderMemo.blockIndex = buildBlockIndex();
        hit = renderMemo.blockIndex.get(blockId);
      }
      return hit ? { page: hit.page, index: hit.index, block: hit.block } : null;
    }
    for (const page of doc.pages) {
      const index = (page.blocks || []).findIndex((item) => item.id === blockId);
      if (index >= 0) return { page, index, block: page.blocks[index] };
    }
    return null;
  }

  // id → 居場所。同じ id が2つあれば、前のページ・前の位置の方(findBlockAnywhere の線形の探し方と同じ)。
  function buildBlockIndex() {
    const index = new Map();
    doc.pages.forEach((page) => (page.blocks || []).forEach((block, position) => {
      if (!index.has(block?.id)) index.set(block?.id, { page, index: position, block });
    }));
    return index;
  }

  function suggestCellObject(block, row, col) {
    const cell = block?.rows?.[row]?.[col];
    if (cell === undefined) return null;
    return cell && typeof cell === "object" ? cell : { text: String(cell ?? "") };
  }

  // 文字の差分の固まり(hunk)。前の文字(before)の上の位置 [start, end) を insert に置き換える。前後の同じ部分を外し、真ん中を
  // 文字ごとの最長共通部分で比べる(長すぎるときは真ん中を1つの固まりにする)。近い固まり(句読点を挟まない4文字以内)はまとめる。
  function suggestHunks(before, after) {
    const a = String(before ?? "");
    const b = String(after ?? "");
    if (a === b) return [];
    let prefix = 0;
    while (prefix < a.length && prefix < b.length && a[prefix] === b[prefix]) prefix += 1;
    let suffix = 0;
    while (suffix < a.length - prefix && suffix < b.length - prefix && a[a.length - 1 - suffix] === b[b.length - 1 - suffix]) suffix += 1;
    const am = a.slice(prefix, a.length - suffix);
    const bm = b.slice(prefix, b.length - suffix);
    const raw = [];
    if (!am.length || !bm.length || am.length * bm.length > 1500000) {
      raw.push({ start: prefix, end: prefix + am.length, insert: bm });
    } else {
      const n = am.length;
      const m = bm.length;
      const width = m + 1;
      const table = new Uint16Array((n + 1) * width);
      for (let i = n - 1; i >= 0; i -= 1) {
        for (let j = m - 1; j >= 0; j -= 1) {
          table[i * width + j] = am[i] === bm[j] ? table[(i + 1) * width + j + 1] + 1 : Math.max(table[(i + 1) * width + j], table[i * width + j + 1]);
        }
      }
      let i = 0;
      let j = 0;
      let current = null;
      const flush = () => {
        if (current) raw.push(current);
        current = null;
      };
      while (i < n || j < m) {
        if (i < n && j < m && am[i] === bm[j]) {
          flush();
          i += 1;
          j += 1;
        } else if (j < m && (i >= n || table[i * width + j + 1] >= table[(i + 1) * width + j])) {
          current = current || { start: prefix + i, end: prefix + i, insert: "" };
          current.insert += bm[j];
          j += 1;
        } else {
          current = current || { start: prefix + i, end: prefix + i, insert: "" };
          current.end = prefix + i + 1;
          i += 1;
        }
      }
      flush();
    }
    // 数・英字・単位の記号の途中では切らない(「25℃ → 23±2℃」が「5 → 3±2」に割れないように)。前後の同じ文字を固まりへ含める。
    const wordChar = (ch) => /[0-9A-Za-z_.±%℃°]/.test(ch || "");
    raw.forEach((hunk, index) => {
      const floor = index ? raw[index - 1].end : 0;
      const ceil = index + 1 < raw.length ? raw[index + 1].start : a.length;
      let start = hunk.start;
      let end = hunk.end;
      while (start > floor && wordChar(a[start - 1]) && (wordChar(a[start]) || wordChar(hunk.insert[0]))) start -= 1;
      while (end < ceil && wordChar(a[end]) && (wordChar(a[end - 1]) || wordChar(hunk.insert[hunk.insert.length - 1]))) end += 1;
      hunk.insert = a.slice(start, hunk.start) + hunk.insert + a.slice(hunk.end, end);
      hunk.start = start;
      hunk.end = end;
    });
    const merged = [];
    raw.forEach((hunk) => {
      const last = merged[merged.length - 1];
      const gap = last ? a.slice(last.end, hunk.start) : null;
      if (last && gap.length <= 4 && !/[。、.,!?！？\n]/.test(gap)) {
        last.insert += gap + hunk.insert;
        last.end = hunk.end;
      } else merged.push({ ...hunk });
    });
    return merged;
  }

  function applySuggestHunks(before, hunks, take) {
    let out = "";
    let cursor = 0;
    hunks.forEach((hunk, index) => {
      out += before.slice(cursor, hunk.start) + (take(index) ? hunk.insert : before.slice(hunk.start, hunk.end));
      cursor = hunk.end;
    });
    return out + before.slice(cursor);
  }

  // 書き換え後の html の文字(本文の text と同じ数え方。無害化してから数える。v242)。
  function suggestHtmlText(html) {
    const holder = document.createElement("template");
    holder.innerHTML = sanitizeInlineHtml(html);
    return serializeBlockText(holder.content);
  }

  // 段落ごとの書き換えの新しい側の見せ方: 書式はそのまま、リンクは押しても移らない印にして行き先を横に書く(v242。差分を
  // 見ている人が、入る中身をそのまま見られるように)。
  function suggestHtmlPreview(html) {
    const holder = document.createElement("template");
    holder.innerHTML = sanitizeInlineHtml(html);
    holder.content.querySelectorAll("a").forEach((anchor) => {
      const link = document.createElement("span");
      link.className = "sg-link";
      link.append(...anchor.childNodes);
      const href = document.createElement("span");
      href.className = "sg-href";
      href.textContent = "(" + (anchor.getAttribute("href") || "") + ")";
      anchor.replaceWith(link, href);
    });
    return holder.content;
  }

  // 書式のある段落(html に <br> 以外の印がある)か。採用するときに書式を残して当てるかを決める。
  function suggestHasFormatting(block) {
    return typeof block?.html === "string" && /<(?!br\s*\/?>)[a-z]/i.test(block.html);
  }

  // 1つの変更の、いまの状態。leaves は決められる最小の単位(語句・セル・ブロック)。stale は元が変わっていて採用できない。
  // 描き直しの間(renderMemo)は、変更ごとの状態を控えて使い回す(#205。以前は描き直し1回の中で、同じ変更の状態を
  // ブロックの印・右のパネル・件数で何度も出し直し、そのたびに文書全体を探していた)。状態を決めるもの(行き先の
  // ブロックとその文字・セル、変更の決め)が控えたときと同じときだけ使う。
  function suggestChangeState(suggestion, change) {
    const memo = renderMemo;
    if (!memo) return computeSuggestChangeState(suggestion, change);
    const inputs = suggestStateInputs(change);
    const kept = memo.suggestStates.get(change);
    if (kept && kept.suggestion === suggestion && kept.inputs.length === inputs.length
      && kept.inputs.every((value, index) => value === inputs[index])) return kept.state;
    const state = computeSuggestChangeState(suggestion, change);
    memo.suggestStates.set(change, { suggestion, inputs, state });
    return state;
  }

  // 状態を決めるもの(変更の中身と決め、行き先のブロックの居場所と文字・セル。足す提案は前のブロックの居場所とページ)。
  function suggestStateInputs(change) {
    const results = change.hunkResults ? change.hunkResults.join("\u0001") : null;
    const common = [change.op, change.result, change.before, change.text, change.html, results, change.block, change.after, change.page];
    if (change.op === "insertBlock") {
      const anchor = change.after ? findBlockAnywhere(change.after) : null;
      return [...common, anchor?.block, anchor?.page, anchor?.index, anchor?.page?.blocks?.length, doc.pages.length];
    }
    const found = findBlockAnywhere(change.block);
    let content = found ? found.block.text : undefined;
    if (change.op === "setCell") {
      const cell = found ? suggestCellObject(found.block, change.row, change.col) : null;
      content = cell ? (cell.covered ? "covered\u0001" : "\u0001") + (cell.text || "") : null;
    }
    return [...common, found?.block, found?.page, found?.index, content, change.row, change.col];
  }

  function computeSuggestChangeState(suggestion, change) {
    const found = change.op === "insertBlock" ? null : findBlockAnywhere(change.block);
    const state = { suggestion, change, page: found?.page || null, block: found?.block || null, leaves: [], stale: false };
    if (change.result) return state;
    if (change.op === "setText") {
      if (!found) { state.stale = true; state.leaves.push({ hunk: null }); return state; }
      const whole = typeof change.html === "string";
      state.whole = whole;
      if (whole) {
        // 書き換え後の html の文字が text と合わない変更は採用できない(見せる差分と入る中身が違ってしまう。v242)。
        state.mismatch = suggestHtmlText(change.html) !== change.text;
        state.stale = state.mismatch || (found.block.text || "") !== (change.before ?? "");
        state.leaves.push({ hunk: null });
        return state;
      }
      const before = change.before ?? "";
      let cached = suggestHunkCache.get(change);
      if (!cached || cached.before !== before || cached.text !== change.text) {
        cached = { before, text: change.text, hunks: suggestHunks(before, change.text) };
        suggestHunkCache.set(change, cached);
      }
      state.hunks = cached.hunks;
      const results = change.hunkResults || [];
      state.stale = (found.block.text || "") !== applySuggestHunks(before, state.hunks, (index) => results[index] === "accepted");
      state.hunks.forEach((hunk, index) => { if (!results[index]) state.leaves.push({ hunk: index }); });
      return state;
    }
    if (change.op === "setCell") {
      const cell = found ? suggestCellObject(found.block, change.row, change.col) : null;
      state.stale = !cell || cell.covered || (cell.text || "") !== (change.before ?? "");
      state.leaves.push({ hunk: null });
      return state;
    }
    if (change.op === "deleteBlock") {
      state.stale = !found;
      state.leaves.push({ hunk: null });
      return state;
    }
    // insertBlock: 前のブロック(after)が無くなっていたら古い(ページの頭に足す提案は page で決める)。
    const anchor = change.after ? findBlockAnywhere(change.after) : null;
    state.page = anchor?.page || doc.pages.find((page) => page.id === change.page) || (change.after ? null : doc.pages[0]);
    state.stale = Boolean(change.after) && !anchor;
    state.insertAt = state.stale || !state.page ? -1 : suggestInsertIndex(change, state.page, anchor ? anchor.index : -1);
    state.leaves.push({ hunk: null });
    return state;
  }

  // 足す位置(ページの中の番号)。同じ所(after)に足す提案が並ぶときは、見えている順(提案の並び)に入れる: この変更より前に
  // 並ぶ変更で採用済みのブロックが、前のブロックのすぐ後ろに続いていれば、その後ろへ(v241。以前はどれも前のブロックの直後に
  // 入れていたので、まとめて採用すると順番が逆になった)。
  function suggestInsertIndex(change, page, anchorIndex) {
    const earlier = new Set();
    for (const suggestion of suggestionList()) {
      const at = suggestion.changes.indexOf(change);
      (at >= 0 ? suggestion.changes.slice(0, at) : suggestion.changes).forEach((item) => {
        if (item.op === "insertBlock" && item.result === "accepted" && item.insertedId && (item.after || null) === (change.after || null)) earlier.add(item.insertedId);
      });
      if (at >= 0) break;
    }
    let index = anchorIndex + 1;
    while (index < page.blocks.length && earlier.has(page.blocks[index].id)) index += 1;
    return index;
  }

  function suggestLeafKey(suggestion, change, hunk) {
    return suggestion.id + "|" + change.id + "|" + (hunk ?? "");
  }

  function pendingSuggestions() {
    return suggestionList().filter((suggestion) => suggestion.status !== "done"
      && suggestion.changes.some((change) => suggestChangeState(suggestion, change).leaves.length));
  }

  function pendingSuggestLeafCount() {
    let count = 0;
    pendingSuggestions().forEach((suggestion) => suggestion.changes.forEach((change) => { count += suggestChangeState(suggestion, change).leaves.length; }));
    return count;
  }

  // 開いた・作り直した文書の提案を整える: 前の値(before)の無い変更は、今の値を前とする(AI が before を書かずに出してもよい)。
  function prepareSuggestions() {
    suggestUnchecked.clear();
    suggestExpanded.clear();
    suggestCollapsed.clear();
    if (!Array.isArray(doc.suggestions)) return;
    doc.suggestions.forEach((suggestion) => suggestion.changes.forEach((change) => {
      if (change.before !== undefined || change.result) return;
      const found = change.block ? findBlockAnywhere(change.block) : null;
      if (change.op === "setText" && found) change.before = found.block.text || "";
      if (change.op === "setCell" && found) change.before = suggestCellObject(found.block, change.row, change.col)?.text || "";
    }));
    suggestPaneOpen = pendingSuggestions().length > 0;
  }

  // 描くときの鍵(部分の描き直しで、提案の状態が変わった行を作り直すため)。
  function suggestBlockRenderKey(blockId) {
    const parts = pendingChangesOfBlock(blockId).map(({ change }) => [change.id, change.hunkResults || null, change.before ?? null, [...suggestUnchecked].filter((key) => key.includes("|" + change.id + "|")).join(",")]);
    return parts.length ? JSON.stringify(parts) : "";
  }

  // そのブロックへの、まだ決めていない変更(提案の並び・変更の並びの順)。描き直しの間は、ブロック id → 変更の索引を
  // 1回だけ作って引く(#205。以前はブロック1つごとに全提案の全変更をなめていた)。
  function pendingChangesOfBlock(blockId) {
    if (renderMemo) {
      renderMemo.pendingByBlock ||= buildPendingChangeIndex();
      return renderMemo.pendingByBlock.get(blockId) || [];
    }
    return buildPendingChangeIndex().get(blockId) || [];
  }

  function buildPendingChangeIndex() {
    const index = new Map();
    suggestionList().forEach((suggestion) => {
      if (suggestion.status === "done") return;
      suggestion.changes.forEach((change) => {
        if (change.result) return;
        if (!index.has(change.block)) index.set(change.block, []);
        index.get(change.block).push({ suggestion, change });
      });
    });
    return index;
  }

  // 足すブロックの提案は、前のブロックのすぐ後ろに「仮の行」として出す(文書のブロックではない。打てない)。
  function withSuggestionGhosts(units) {
    const pageId = currentPage().id;
    const ghosts = [];
    suggestionList().forEach((suggestion) => {
      if (suggestion.status === "done") return;
      suggestion.changes.forEach((change) => {
        if (change.op !== "insertBlock" || change.result) return;
        const state = suggestChangeState(suggestion, change);
        if (state.stale || state.page?.id !== pageId) return;
        let ghost = suggestGhosts.get(change);
        if (!ghost) {
          const { columnGroup, columnIndex, columnWidth, ...item } = JSON.parse(JSON.stringify(change.item));
          ghost = { ...item, id: "sg-" + change.id };
          suggestGhosts.set(change, ghost);
          suggestGhostChange.set(ghost, { suggestion, change });
        }
        const prior = state.insertAt > 0 ? state.page.blocks[state.insertAt - 1] : null;
        ghosts.push({ after: prior ? prior.id : null, unit: { id: "g:" + change.id, groupId: null, blocks: [ghost] } });
      });
    });
    if (!ghosts.length) return units;
    const out = [];
    ghosts.filter((entry) => !entry.after).forEach((entry) => out.push(entry.unit));
    units.forEach((unit) => {
      out.push(unit);
      unit.blocks.forEach((block) => ghosts.filter((entry) => entry.after === block.id).forEach((entry) => out.push(entry.unit)));
    });
    return out;
  }

  // 描いた行に提案の印を付ける(renderBlock の最後に呼ぶ)。
  function decorateSuggestionRow(row, block) {
    const ghost = suggestGhostChange.get(block);
    if (ghost) {
      row.classList.add("sg-block-ins");
      if (suggestUnchecked.has(suggestLeafKey(ghost.suggestion, ghost.change, null))) row.classList.add("sg-off");
      row.querySelectorAll('[contenteditable="true"]').forEach((node) => { node.contentEditable = "false"; });
      row.dataset.sgLeaf = suggestLeafKey(ghost.suggestion, ghost.change, null);
      return;
    }
    pendingChangesOfBlock(block.id).forEach(({ suggestion, change }) => {
      const state = suggestChangeState(suggestion, change);
      if (state.stale || !state.leaves.length) return;
      if (change.op === "deleteBlock") {
        row.classList.add("sg-block-del");
        if (suggestUnchecked.has(suggestLeafKey(suggestion, change, null))) row.classList.add("sg-off");
        row.dataset.sgLeaf = suggestLeafKey(suggestion, change, null);
        row.querySelectorAll('[contenteditable="true"]').forEach((node) => { node.contentEditable = "false"; });
      } else if (change.op === "setText") {
        const content = row.querySelector(":scope > .block-content") || row.querySelector(".block-content");
        if (!content) return;
        content.contentEditable = "false";
        content.classList.add("sg-text");
        content.replaceChildren(...suggestTextNodes(suggestion, change, state));
      } else if (change.op === "setCell") {
        const td = row.querySelector('.editor-table [data-row="' + change.row + '"][data-cell="' + change.col + '"]');
        if (!td) return;
        const key = suggestLeafKey(suggestion, change, null);
        td.contentEditable = "false";
        td.classList.add("sg-cell");
        if (suggestUnchecked.has(key)) td.classList.add("sg-off");
        td.dataset.sgLeaf = key;
        const old = document.createElement("span");
        old.className = "sg-old";
        old.textContent = change.before ?? "";
        const next = document.createElement("span");
        next.className = "sg-new";
        next.textContent = change.text;
        td.replaceChildren(old, next);
      }
    });
  }

  // 段落の差分を、決めた語句は決めた文字で、まだの語句は「消える(赤) + 増える(緑)」で並べる。
  function suggestTextNodes(suggestion, change, state) {
    const nodes = [];
    const text = (value, className, key) => {
      if (!value) return;
      const span = document.createElement("span");
      if (className) span.className = className;
      if (key) span.dataset.sgLeaf = key;
      span.textContent = value;
      nodes.push(span);
    };
    if (state.whole) {
      const key = suggestLeafKey(suggestion, change, null);
      const off = suggestUnchecked.has(key) ? " sg-off" : "";
      text(change.before ?? "", "sg-del" + off, key);
      const next = document.createElement("span");
      next.className = "sg-ins" + off;
      next.dataset.sgLeaf = key;
      next.append(suggestHtmlPreview(change.html));
      nodes.push(next);
      return nodes;
    }
    const before = change.before ?? "";
    const results = change.hunkResults || [];
    let cursor = 0;
    state.hunks.forEach((hunk, index) => {
      text(before.slice(cursor, hunk.start));
      if (results[index] === "accepted") text(hunk.insert, "sg-done");
      else if (results[index] === "rejected") text(before.slice(hunk.start, hunk.end));
      else {
        const key = suggestLeafKey(suggestion, change, index);
        const off = suggestUnchecked.has(key) ? " sg-off" : "";
        text(before.slice(hunk.start, hunk.end), "sg-del" + off, key);
        text(hunk.insert, "sg-ins" + off, key);
      }
      cursor = hunk.end;
    });
    text(before.slice(cursor));
    return nodes;
  }

  // ---- 決める ----
  // leaves: [{ suggestion, change, hunk }]。採用は文書へ入れ、戻すは何もしない。どちらも結果を残す。まとめて1回の Undo。
  function decideSuggestionLeaves(leaves, verdict) {
    const targets = leaves.filter(({ suggestion, change }) => suggestion.status !== "done" && !change.result);
    if (!targets.length) return;
    const lockedPages = new Set();
    const usable = targets.filter((leaf) => {
      const state = suggestChangeState(leaf.suggestion, leaf.change);
      const page = state.page;
      if (page && pageIsLocked(page)) {
        lockedPages.add(page.id);
        return false;
      }
      return verdict === "rejected" || !state.stale;
    });
    if (!usable.length) {
      setStatus(lockedPages.size ? "ロックされたページの提案は決められません" : "元が変わっている提案は採用できません(戻すことはできます)", "warn");
      return;
    }
    const undoTop = undoStack.at(-1);
    const redoBefore = redoStack;
    saveHistory();
    let accepted = 0;
    let rejected = 0;
    let skipped = 0;
    // 変更ごとにまとめる(同じ段落の語句は一緒に当てる。1語句ずつ当てると、前の語句の結果を前提に次を当てることになる)。
    const groups = new Map();
    usable.forEach((leaf) => {
      if (!groups.has(leaf.change)) groups.set(leaf.change, { suggestion: leaf.suggestion, change: leaf.change, hunks: [] });
      if (leaf.hunk !== null && leaf.hunk !== undefined) groups.get(leaf.change).hunks.push(leaf.hunk);
    });
    // 当てる順は 文字・セル → 足す → 消す(先に消すと、同じブロックの書き換えや、そこを前とする追加の行き先が無くなる)。
    // 1つ当てるたびに文書が変わるので、当てる直前にもう一度「古くないか」を確かめる。古ければ当てずに残す(v241。以前は
    // 最初に1回だけ確かめていたので、消したブロックへ書き換えを当てようとして止まった)。
    const rank = { setText: 0, setCell: 0, insertBlock: 1, deleteBlock: 2 };
    const touchedPages = new Set();
    [...groups.values()].sort((a, b) => rank[a.change.op] - rank[b.change.op]).forEach(({ suggestion, change, hunks }) => {
      const state = suggestChangeState(suggestion, change);
      if (verdict === "accepted" && (state.stale || (change.op !== "insertBlock" && !state.block))) {
        skipped += hunks.length || 1;
        return;
      }
      if (change.op === "setText" && !state.whole) {
        const results = (change.hunkResults || []).slice();
        while (results.length < state.hunks.length) results.push(null);
        if (verdict === "accepted") {
          if (!applySuggestTextHunks(state.block, change.before ?? "", state.hunks, results, hunks)) {
            skipped += hunks.length;
            return;
          }
          accepted += hunks.length;
        } else rejected += hunks.length;
        hunks.forEach((index) => { results[index] = verdict; });
        change.hunkResults = results;
        if (results.every(Boolean)) {
          change.result = results.every((value) => value === "accepted") ? "accepted" : results.every((value) => value === "rejected") ? "rejected" : "partial";
        }
        return;
      }
      if (verdict === "accepted") {
        if (!applySuggestionChange(suggestion, change, state)) {
          skipped += 1;
          return;
        }
        if (state.page) touchedPages.add(state.page);
        accepted += 1;
      } else rejected += 1;
      change.result = verdict;
    });
    if (!accepted && !rejected) {
      // 1つも当てられなかった(どれも当てる直前に古くなった・参照などの途中にかかった): 積んだ Undo の段を外し、文書は
      // 変わっていないので未保存の印も付けない(v242)。
      if (undoStack.at(-1) !== undoTop) undoStack.pop();
      redoStack = redoBefore;
      setStatus("採用できなかった " + skipped + " か所(元が変わった・参照などの途中にかかる)", "warn");
      return;
    }
    touchedPages.forEach((page) => normalizeColumnLayouts(page.blocks));
    suggestionList().forEach((suggestion) => {
      if (suggestion.status !== "done" && suggestion.changes.every((change) => change.result)) suggestion.status = "done";
    });
    render();
    markDirty();
    const parts = [];
    if (accepted) parts.push("採用 " + accepted + " か所");
    if (rejected) parts.push("戻す " + rejected + " か所");
    if (skipped) parts.push("採用できなかった " + skipped + " か所(元が変わった・参照などの途中にかかる)");
    setStatus(parts.join("・"), skipped ? "warn" : undefined);
  }

  // 段落へ語句を当てる。picked は今回採用する語句の番号。今の文字は「前の文字に、前に採用した語句を当てたもの」なので、位置を
  // その上へ移してから当てる。書式のある段落は、書式を残したまま文字だけを当てる(v241。以前は html を空にして書式が消えた)。
  function applySuggestTextHunks(block, before, hunks, results, picked) {
    const chosen = new Set(picked);
    const edits = [];
    let shift = 0;
    hunks.forEach((hunk, index) => {
      if (chosen.has(index)) edits.push({ start: hunk.start + shift, end: hunk.end + shift, insert: hunk.insert });
      else if (results[index] === "accepted") shift += hunk.insert.length - (hunk.end - hunk.start);
    });
    const nextText = applySuggestHunks(before, hunks, (index) => results[index] === "accepted" || chosen.has(index));
    if (suggestHasFormatting(block)) {
      const html = applyHunksToInlineHtml(block.html, block.text || "", edits, nextText);
      if (html === null) return false;
      block.html = html;
    } else block.html = "";
    block.text = nextText;
    return true;
  }

  // 書式のある段落の html に、文字の差分(edits。今の文字 text の上の位置)を後ろから当てる。書式の印はそのまま残し、増える
  // 文字はその位置の前の文字と同じ書式に入る。参照の印・コード・数式・改行は1つの塊で、途中にかかる差分は当てない(null)。
  // 文字の数え方は serializeInlineMarkdown と同じ(コードは `…`、数式は $$…$$、改行は \n)。当てた結果が expected と
  // 合わないときも null(呼ぶ側は採用しない)。
  function applyHunksToInlineHtml(html, text, edits, expected) {
    const template = document.createElement("template");
    template.innerHTML = sanitizeInlineHtml(html);
    const host = template.content;
    const walker = document.createTreeWalker(host, NodeFilter.SHOW_TEXT);
    for (let node = walker.nextNode(); node; node = walker.nextNode()) {
      if (node.nodeValue.includes("\u200b")) node.nodeValue = node.nodeValue.replaceAll("\u200b", "");
    }
    const atomic = (node) => node.nodeName === "BR" || (node.nodeName === "CODE" && node.classList.contains("inline-code"))
      || (node.nodeName === "SPAN" && (node.classList.contains("inline-math") || node.matches(MARK_SELECTOR)));
    const atomText = (node) => (node.nodeName === "BR" ? "\n" : node.nodeName === "CODE" ? "`" + inlineCodeValue(node) + "`"
      : node.classList.contains("inline-math") ? "$$" + inlineMathValue(node) + "$$" : node.textContent || "");
    const segments = () => {
      const list = [];
      let pos = 0;
      const walk = (parent) => parent.childNodes.forEach((child) => {
        if (child.nodeType === Node.TEXT_NODE) {
          list.push({ node: child, start: pos, end: pos + child.nodeValue.length, text: true });
          pos += child.nodeValue.length;
        } else if (child.nodeType === Node.ELEMENT_NODE && atomic(child)) {
          const length = atomText(child).length;
          list.push({ node: child, start: pos, end: pos + length, text: false });
          pos += length;
        } else if (child.nodeType === Node.ELEMENT_NODE) walk(child);
      });
      walk(host);
      return list;
    };
    const textOf = (list) => list.map((seg) => (seg.text ? seg.node.nodeValue : atomText(seg.node))).join("");
    const matches = (value, target) => value === target || value === target + "\n";
    if (!matches(textOf(segments()), text)) return null;
    for (const edit of [...edits].sort((a, b) => b.start - a.start)) {
      const list = segments();
      const cuts = (seg, at) => at > seg.start && at < seg.end;
      if (list.some((seg) => !seg.text && (cuts(seg, edit.start) || cuts(seg, edit.end)))) return null;
      list.forEach((seg) => {
        const from = Math.max(edit.start, seg.start);
        const to = Math.min(edit.end, seg.end);
        if (to <= from) return;
        if (seg.text) seg.node.nodeValue = seg.node.nodeValue.slice(0, from - seg.start) + seg.node.nodeValue.slice(to - seg.start);
        else seg.node.remove();
      });
      if (!edit.insert) continue;
      const fragment = document.createDocumentFragment();
      edit.insert.split("\n").forEach((piece, index) => {
        if (index) fragment.append(document.createElement("br"));
        if (piece) fragment.append(document.createTextNode(piece));
      });
      // 入れる場所: その位置で終わる・その位置を含む文字(前の文字の書式)。無ければ、その位置から始まる塊の前、それも無ければ最後。
      const at = list.find((seg) => seg.text && seg.start <= edit.start && edit.start <= seg.end);
      if (at) {
        const tail = at.node.splitText(edit.start - at.start);
        tail.parentNode.insertBefore(fragment, tail);
      } else {
        const next = list.find((seg) => seg.start >= edit.start && seg.node.parentNode);
        if (next) next.node.parentNode.insertBefore(fragment, next.node);
        else host.append(fragment);
      }
    }
    if (!matches(textOf(segments()), expected)) return null;
    return sanitizeInlineHtml(template.innerHTML);
  }

  function applySuggestionChange(suggestion, change, state = suggestChangeState(suggestion, change)) {
    if (change.op === "setText") {
      state.block.text = change.text;
      state.block.html = typeof change.html === "string" ? sanitizeInlineHtml(change.html) : "";
    } else if (change.op === "setCell") {
      const rows = state.block.rows;
      const cell = rows[change.row][change.col];
      if (cell && typeof cell === "object") cell.text = change.text;
      else rows[change.row][change.col] = { text: change.text };
    } else if (change.op === "deleteBlock") {
      const found = findBlockAnywhere(change.block);
      if (!found) return false;
      found.page.blocks.splice(found.index, 1);
      if (!found.page.blocks.length) found.page.blocks.push({ id: id(), type: "paragraph", text: "" });
    } else if (change.op === "insertBlock") {
      const page = state.page;
      if (!page || state.insertAt < 0) return false;
      const item = JSON.parse(JSON.stringify(change.item));
      if (findBlockAnywhere(item.id)) item.id = id();
      // 前のブロックが段組みの中なら、同じ列に入れる(提案の item は段組みを持たない。開くときに外す)。
      const anchorBlock = change.after ? findBlockAnywhere(change.after)?.block : null;
      if (anchorBlock?.columnGroup) copyColumnLayout(anchorBlock, item);
      page.blocks.splice(state.insertAt, 0, item);
      change.insertedId = item.id;
    }
    return true;
  }

  // ---- 選ぶ(チェック) ----
  function suggestNodeLeaves(node) {
    return node.leaves || node.children.flatMap(suggestNodeLeaves);
  }

  // 提案の木: 提案 → ブロック(表は列) → 1か所。
  function suggestionTree(suggestion) {
    const byBlock = new Map();
    const order = [];
    suggestion.changes.forEach((change) => {
      const state = suggestChangeState(suggestion, change);
      if (!state.leaves.length) return;
      const targetId = change.op === "insertBlock" ? "ins:" + change.id : change.block;
      if (!byBlock.has(targetId)) {
        byBlock.set(targetId, { key: suggestion.id + "|b|" + targetId, label: suggestTargetLabel(change, state), states: [], targetId });
        order.push(byBlock.get(targetId));
      }
      byBlock.get(targetId).states.push(state);
    });
    return order.map((group) => {
      const first = group.states[0];
      if (first.change.op === "setCell") {
        const columns = new Map();
        group.states.forEach((state) => {
          const col = state.change.col;
          if (!columns.has(col)) columns.set(col, []);
          columns.get(col).push(state);
        });
        const children = [...columns.entries()].sort((a, b) => a[0] - b[0]).map(([col, states]) => ({
          key: group.key + "|c" + col,
          label: "列 " + columnLabel(col) + suggestColumnName(first.block, col),
          leaves: states.map((state) => suggestLeaf(state, null)),
        }));
        return children.length === 1
          ? { key: group.key, label: group.label + " · " + children[0].label, leaves: children[0].leaves, targetId: group.targetId }
          : { key: group.key, label: group.label, children, targetId: group.targetId };
      }
      const leaves = group.states.flatMap((state) => state.leaves.map((leaf) => suggestLeaf(state, leaf.hunk)));
      return { key: group.key, label: group.label, leaves, targetId: group.targetId };
    });
  }

  function suggestColumnName(block, col) {
    const head = block?.tableHeader ? suggestCellObject(block, 0, col)?.text : "";
    return head ? " " + head : "";
  }

  function suggestShort(value, max = 18) {
    const text = String(value ?? "").replace(/\s+/g, " ").trim();
    return text.length > max ? text.slice(0, max) + "…" : text || "(空)";
  }

  function suggestTargetLabel(change, state) {
    const kind = { setText: "書き換え", setCell: "表のセル", insertBlock: "追加", deleteBlock: "削除" }[change.op];
    if (change.op === "insertBlock") return "追加: " + suggestShort(change.item.text || change.item.caption || change.item.type, 22);
    const block = state.block;
    if (!block) return kind + ": (見つからないブロック)";
    if (block.type === "table") return (block.caption ? block.caption : "表") ;
    return (change.op === "deleteBlock" ? "削除: " : "") + suggestShort(block.text || block.caption || block.type, 22);
  }

  function suggestLeaf(state, hunk) {
    const { suggestion, change } = state;
    let label;
    if (change.op === "setCell") label = columnLabel(change.col) + (change.row + 1) + ": " + suggestShort(change.before, 10) + " → " + suggestShort(change.text, 10);
    else if (change.op === "setText" && hunk !== null && hunk !== undefined) {
      const piece = state.hunks[hunk];
      const removed = (change.before ?? "").slice(piece.start, piece.end);
      label = !removed ? "＋ " + suggestShort(piece.insert, 24) : !piece.insert ? "− " + suggestShort(removed, 24)
        : suggestShort(removed, 14) + " → " + suggestShort(piece.insert, 14);
    } else if (change.op === "setText") label = "段落ごと書き換え";
    else if (change.op === "deleteBlock") label = "ブロックを消す";
    else label = "ブロックを足す";
    return { key: suggestLeafKey(suggestion, change, hunk), label, stale: state.stale, staleLabel: state.mismatch ? "中身が合わない" : "古い", ref: { suggestion, change, hunk } };
  }

  function suggestCheckState(leaves) {
    const usable = leaves.filter((leaf) => !leaf.stale);
    if (!usable.length) return "off";
    const on = usable.filter((leaf) => !suggestUnchecked.has(leaf.key)).length;
    return on === usable.length ? "on" : on ? "part" : "off";
  }

  function setSuggestLeavesChecked(leaves, checked) {
    leaves.forEach((leaf) => (checked ? suggestUnchecked.delete(leaf.key) : suggestUnchecked.add(leaf.key)));
    render();
  }

  // ---- 右のパネル ----
  // 右のパネル(提案・文書チェック)の上端は、道具の帯の下端(Issue #243)。検索・置換のバー(帯の右下に浮かぶ)が開いている間は、
  // その下から(v243)。以前は CSS の決め打ち 96px で、帯(実際は 124px)の下の部分がパネルの下になり、狭い画面(800px)では文字色・
  // 背景色のボタンが押せなかった。帯は画面の幅で折り返して高さが変わり、バーは開閉・置換の行の出し入れで高さが変わるので、
  // どちらも大きさが変わるたびに置き直す(ツールバーは z-index 5 の重なりの中にあり、パネルより下になる)。
  // 右のパネルを足すときもこれを通す(上端を数字で決め打ちしない。文書チェックのパネル(Issue #236)もここ)。
  const belowToolbarPanes = new Set();
  let belowToolbarObserver = null;
  function placeBelowToolbar() {
    const searchBar = document.querySelector("#search-bar");
    const toolbarBottom = toolbarEl ? toolbarEl.getBoundingClientRect().bottom : 0;
    const searchRect = searchBar && !searchBar.hidden ? searchBar.getBoundingClientRect() : null;
    const top = Math.max(toolbarBottom, searchRect?.height ? searchRect.bottom + 8 : 0);
    belowToolbarPanes.forEach((pane) => { pane.style.top = top > 0 ? Math.ceil(top) + "px" : ""; });
  }
  function keepBelowToolbar(pane) {
    belowToolbarPanes.add(pane);
    if (!belowToolbarObserver && typeof ResizeObserver === "function") {
      belowToolbarObserver = new ResizeObserver(placeBelowToolbar);
      const searchBar = document.querySelector("#search-bar");
      if (toolbarEl) belowToolbarObserver.observe(toolbarEl);
      if (searchBar) belowToolbarObserver.observe(searchBar);
    }
    placeBelowToolbar();
  }

  function ensureSuggestUi() {
    if (suggestPaneEl) return;
    suggestPaneEl = document.createElement("aside");
    suggestPaneEl.className = "suggest-pane";
    suggestPaneEl.id = "suggest-pane";
    suggestPaneEl.setAttribute("role", "complementary");
    suggestPaneEl.setAttribute("aria-label", "提案");
    suggestPaneEl.hidden = true;
    document.body.append(suggestPaneEl);
    keepBelowToolbar(suggestPaneEl);
    suggestToggleEl = document.createElement("button");
    suggestToggleEl.type = "button";
    suggestToggleEl.className = "suggest-toggle";
    suggestToggleEl.id = "suggest-toggle";
    suggestToggleEl.hidden = true;
    suggestToggleEl.addEventListener("click", () => {
      suggestPaneOpen = !suggestPaneOpen;
      // 右のパネルは1つずつ(文書チェックのパネルと同じ場所。Issue #236)。
      if (suggestPaneOpen) closeCheckPane();
      renderSuggestPane();
    });
    document.querySelector("#menubar")?.append(suggestToggleEl);
  }

  // パネルは提案の数・状態を何度も読む(件数・まとまり・1か所ずつ)ので、作る間は状態の控えを使う(#205)。
  function renderSuggestPane() {
    withRenderMemo(renderSuggestPaneNow);
  }

  function renderSuggestPaneNow() {
    ensureSuggestUi();
    const pending = pendingSuggestions();
    const leafCount = pendingSuggestLeafCount();
    suggestToggleEl.hidden = !pending.length;
    suggestToggleEl.textContent = "提案 " + leafCount;
    suggestToggleEl.setAttribute("aria-pressed", suggestPaneOpen && pending.length ? "true" : "false");
    const open = suggestPaneOpen && pending.length > 0;
    if (open) closeCheckPane();
    suggestPaneEl.hidden = !open;
    document.querySelector(".app")?.classList.toggle("suggest-pane-reserved", open && window.innerWidth >= 1100);
    if (!open) {
      hideSuggestPopup();
      return;
    }
    const scroll = suggestPaneEl.scrollTop;
    const parts = [];
    const head = document.createElement("div");
    head.className = "sg-pane-head";
    head.innerHTML = "<b>提案</b>";
    const sub = document.createElement("span");
    sub.className = "sg-pane-sub";
    sub.textContent = pending.length + " 件・まだ決めていない所 " + leafCount + " か所";
    const close = document.createElement("button");
    close.type = "button";
    close.className = "sg-pane-close";
    close.textContent = "×";
    close.title = "閉じる(提案は残ります)";
    close.addEventListener("click", () => {
      suggestPaneOpen = false;
      renderSuggestPane();
    });
    head.append(sub, close);
    parts.push(head);
    pending.forEach((suggestion) => parts.push(renderSuggestSection(suggestion)));
    if (pending.length > 1) {
      const all = pending.flatMap((suggestion) => suggestionTree(suggestion).flatMap(suggestNodeLeaves));
      parts.push(suggestActions(all, "すべての提案", true));
    }
    suggestPaneEl.replaceChildren(...parts);
    suggestPaneEl.scrollTop = scroll;
  }

  function renderSuggestSection(suggestion) {
    const section = document.createElement("section");
    section.className = "sg-section";
    section.dataset.suggestion = suggestion.id;
    const who = document.createElement("div");
    who.className = "sg-who";
    const dot = document.createElement("span");
    dot.className = "sg-dot sg-kind-" + suggestion.author.kind;
    dot.textContent = (suggestion.author.name || "?").slice(0, 1).toUpperCase();
    const name = document.createElement("span");
    name.textContent = suggestion.author.name + (suggestion.author.kind === "ai" ? "(AI)" : suggestion.author.kind === "tool" ? "(道具)" : "");
    who.append(dot, name);
    section.append(who);
    if (suggestion.title) {
      const title = document.createElement("div");
      title.className = "sg-title";
      title.textContent = suggestion.title;
      section.append(title);
    }
    if (suggestion.reason) {
      const reason = document.createElement("div");
      reason.className = "sg-reason";
      reason.textContent = suggestion.reason;
      section.append(reason);
    }
    const nodes = suggestionTree(suggestion);
    const rootLeaves = nodes.flatMap(suggestNodeLeaves);
    const tree = document.createElement("ul");
    tree.className = "sg-tree";
    nodes.forEach((node) => tree.append(renderSuggestNode(node, 0)));
    section.append(tree, suggestActions(rootLeaves, "", false));
    return section;
  }

  function renderSuggestNode(node, depth) {
    const item = document.createElement("li");
    const line = document.createElement("div");
    line.className = "sg-node";
    const leaves = suggestNodeLeaves(node);
    const isLeafNode = !node.children && !node.leaves;
    const hasKids = Boolean(node.children || (node.leaves && (node.leaves.length > 1 || node.children)));
    // 既定の開閉: ブロックの段は開く(1か所だけなら中身を出さない)、列の段は閉じる。
    const open = hasKids && (suggestExpanded.has(node.key) || (!suggestCollapsed.has(node.key) && depth === 0 && leaves.length <= 12));
    const twisty = document.createElement("button");
    twisty.type = "button";
    twisty.className = "sg-twisty";
    twisty.textContent = hasKids ? (open ? "▾" : "▸") : "";
    twisty.disabled = !hasKids;
    twisty.addEventListener("click", () => {
      if (open) { suggestExpanded.delete(node.key); suggestCollapsed.add(node.key); }
      else { suggestExpanded.add(node.key); suggestCollapsed.delete(node.key); }
      renderSuggestPane();
    });
    const state = suggestCheckState(leaves);
    const box = document.createElement("button");
    box.type = "button";
    box.className = "sg-box sg-box-" + state;
    box.setAttribute("role", "checkbox");
    box.setAttribute("aria-checked", state === "on" ? "true" : state === "part" ? "mixed" : "false");
    box.textContent = state === "on" ? "✓" : state === "part" ? "−" : "";
    box.disabled = leaves.every((leaf) => leaf.stale);
    box.addEventListener("click", () => setSuggestLeavesChecked(leaves, state !== "on"));
    const label = document.createElement("button");
    label.type = "button";
    label.className = "sg-label";
    label.textContent = node.label;
    label.addEventListener("click", () => revealSuggestionTarget(leaves[0]?.ref));
    const count = document.createElement("span");
    count.className = "sg-count";
    const usable = leaves.filter((leaf) => !leaf.stale);
    count.textContent = leaves.length > 1 || node.children ? usable.filter((leaf) => !suggestUnchecked.has(leaf.key)).length + " / " + leaves.length : leaves[0]?.stale ? leaves[0].staleLabel || "古い" : "";
    line.append(twisty, box, label, count);
    item.append(line);
    if (open) {
      const list = document.createElement("ul");
      (node.children || node.leaves.map((leaf) => ({ key: leaf.key, label: leaf.label, leaves: [leaf] }))).forEach((child) => list.append(renderSuggestNode(child, depth + 1)));
      item.append(list);
    }
    if (isLeafNode) return item;
    return item;
  }

  function suggestActions(leaves, prefix, all) {
    const bar = document.createElement("div");
    bar.className = "sg-actions";
    const picked = leaves.filter((leaf) => !leaf.stale && !suggestUnchecked.has(leaf.key));
    const accept = document.createElement("button");
    accept.type = "button";
    accept.className = "sg-btn ok";
    accept.textContent = all ? "すべて採用" : picked.length === leaves.length ? "採用(" + picked.length + " か所)" : "選んだ " + picked.length + " か所を採用";
    accept.disabled = !picked.length;
    accept.addEventListener("click", () => decideSuggestionLeaves((all ? leaves.filter((leaf) => !leaf.stale) : picked).map((leaf) => leaf.ref), "accepted"));
    const reject = document.createElement("button");
    reject.type = "button";
    reject.className = "sg-btn ng";
    reject.textContent = all ? "すべて戻す" : picked.length === leaves.length || !picked.length ? "戻す" : "選んだ所を戻す";
    reject.addEventListener("click", () => decideSuggestionLeaves((all || !picked.length ? leaves : picked).map((leaf) => leaf.ref), "rejected"));
    if (prefix) {
      const label = document.createElement("span");
      label.className = "sg-actions-label";
      label.textContent = prefix;
      bar.append(label);
    }
    bar.append(accept, reject);
    return bar;
  }

  function revealSuggestionTarget(ref) {
    if (!ref) return;
    const state = suggestChangeState(ref.suggestion, ref.change);
    const page = state.page;
    if (page && page.id !== currentPage().id) showPage(page.id);
    const targetId = ref.change.op === "insertBlock" ? "sg-" + ref.change.id : ref.change.block;
    // 行き先の id はファイル由来(開くときにも確かめているが、セレクタへ入れる前にもう一度。P25・v159)。
    if (!fmt.isSafeId(ref.change.op === "insertBlock" ? ref.change.id : targetId)) return;
    if (ref.change.op !== "insertBlock") revealBlock(targetId);
    const row = blocksEl.querySelector('.block[data-id="' + targetId + '"]');
    if (!row) return;
    row.scrollIntoView({ block: "center", behavior: "smooth" });
    flashRow(row, "sg-flash");
  }

  // 移った先の行を少しの間だけ色で知らせる(提案の行き先・参照とリンクの行き先。Issue #176)。続けて同じ行へ移っても、もう一度光らせる。
  function flashRow(row, className) {
    row.classList.remove(className);
    void row.offsetWidth;
    row.classList.add(className);
  }

  // ---- 文書チェック(Issue #236) ----
  // File メニュー・コマンドパレットの「文書をチェック」で、右のパネル(提案のパネルと同じ場所・同じ作り)に結果を出す。
  // 判定は document-check.js(既存の判定の窓口を使う)。ここは画面: パネル・項目を選んで移る・再チェック・古くなった印。
  // チェックは文書を読むだけで、結果は文書に保存しない(別の文書を開いたら捨てる)。保存・配布は止めない(知らせるだけ)。
  const documentCheck = window.DocumentCheck.create({ tableFormula, chartTools, diagram: (text) => mermaidJob(text) });
  let checkPaneEl = null;
  let checkPaneOpen = false;
  let checkReport = null;
  // チェックした時の文書(別の文書を開いたら捨てる)と編集の番号(変わったら「チェックのあとで変わりました」)。
  let checkSession = null;
  let checkEditSerial = -1;
  let checkRun = 0;
  let checkSelectedKey = "";

  function ensureCheckUi() {
    if (checkPaneEl) return;
    checkPaneEl = document.createElement("aside");
    checkPaneEl.className = "suggest-pane check-pane";
    checkPaneEl.id = "check-pane";
    checkPaneEl.setAttribute("role", "complementary");
    checkPaneEl.setAttribute("aria-label", "文書チェック");
    checkPaneEl.hidden = true;
    document.body.append(checkPaneEl);
    keepBelowToolbar(checkPaneEl);
  }

  // 「文書をチェック」: パネルを開き、文書全体を調べ直す(開いている間に押せば再チェック)。
  async function runDocumentCheck() {
    ensureCheckUi();
    if (suggestPaneOpen) {
      suggestPaneOpen = false;
      renderSuggestPane();
    }
    checkPaneOpen = true;
    const run = ++checkRun;
    checkSession = documentSessionId;
    checkEditSerial = editSerial;
    checkReport = { status: "checking", issues: [], unchecked: [], counts: null, pending: 0 };
    renderCheckPane();
    let report;
    try {
      report = await documentCheck.check(doc, {
        onProgress: (partial) => {
          if (run !== checkRun) return;
          checkReport = partial;
          renderCheckPane();
        },
      });
    } catch (error) {
      report = { status: "failed", issues: [], unchecked: [], counts: null, error: String(error?.message || error) };
    }
    if (run !== checkRun || checkSession !== documentSessionId) return;
    checkReport = report;
    renderCheckPane();
    const problems = report.issues.length;
    setStatus(report.status === "ok" ? "文書チェック: 見つかった問題はありません"
      : report.status === "failed" ? "文書チェックを最後までできませんでした"
        : "文書チェック: 問題 " + problems + " 件" + (report.unchecked.length ? "・確かめられなかった項目 " + report.unchecked.length + " 件" : ""));
  }

  function closeCheckPane() {
    if (!checkPaneOpen) return;
    checkPaneOpen = false;
    renderCheckPane();
  }

  // 別の文書になったら、前の文書の結果は捨てる(パネルも閉じる)。
  function resetDocumentCheck() {
    checkRun += 1;
    checkReport = null;
    checkSelectedKey = "";
    closeCheckPane();
  }

  // 編集のたびに(setEdited)、開いているパネルの「チェックのあとで変わりました」を付け直す(作り直さない)。
  function syncCheckStale() {
    if (!checkPaneEl || checkPaneEl.hidden) return;
    const stale = checkPaneEl.querySelector(".ck-stale");
    if (stale) stale.hidden = !checkIsStale();
  }

  function checkIsStale() {
    return Boolean(checkReport) && checkReport.status !== "checking" && (checkSession !== documentSessionId || checkEditSerial !== editSerial);
  }

  function checkIssueKey(issue) {
    return [issue.category, issue.pageId, issue.blockId, issue.cell ? issue.cell.row + ":" + issue.cell.col : "", issue.title].join("|");
  }

  function renderCheckPane() {
    if (!checkPaneEl) return;
    const open = checkPaneOpen && Boolean(checkReport);
    checkPaneEl.hidden = !open;
    document.querySelector(".app")?.classList.toggle("check-pane-reserved", open && window.innerWidth >= 1100);
    if (!open) return;
    const report = checkReport;
    const scroll = checkPaneEl.scrollTop;
    const parts = [];
    const head = document.createElement("div");
    head.className = "sg-pane-head";
    head.innerHTML = "<b>文書チェック</b>";
    const close = document.createElement("button");
    close.type = "button";
    close.className = "sg-pane-close";
    close.textContent = "×";
    close.title = "閉じる";
    close.setAttribute("aria-label", "文書チェックを閉じる");
    close.addEventListener("click", closeCheckPane);
    head.append(close);
    parts.push(head);

    // 結果の見出し: 問題なし / 問題あり / 確かめられなかった項目あり / 調べている途中。
    const summary = document.createElement("div");
    summary.className = "ck-summary ck-" + report.status;
    summary.setAttribute("role", "status");
    const summaryTitle = document.createElement("div");
    summaryTitle.className = "ck-summary-title";
    const issues = report.issues.length;
    const unchecked = report.unchecked.length;
    summaryTitle.textContent = report.status === "checking" ? (report.pending ? "図を描いて確かめています(" + report.pending + " 件)…" : "チェックしています…")
      : report.status === "failed" ? "チェックを最後までできませんでした"
        : report.status === "ok" ? "見つかった問題はありません"
          : issues ? "問題が " + issues + " 件あります" : "確かめられなかった項目があります";
    summary.append(summaryTitle);
    if (report.status !== "checking" && issues && unchecked) {
      const more = document.createElement("div");
      more.className = "ck-summary-sub";
      more.textContent = "ほかに確かめられなかった項目が " + unchecked + " 件あります";
      summary.append(more);
    }
    if (report.counts) {
      const counts = report.counts;
      const scope = document.createElement("div");
      scope.className = "ck-summary-sub";
      scope.textContent = "調べたもの: " + counts.pages + " ページ・参照とリンク " + counts.references + "・表の式 " + counts.formulas
        + "・グラフ " + counts.charts + "・図 " + counts.diagrams + "・数式 " + counts.math;
      summary.append(scope);
    }
    if (report.error) {
      const failed = document.createElement("div");
      failed.className = "ck-summary-sub";
      failed.textContent = report.error;
      summary.append(failed);
    }
    parts.push(summary);

    const stale = document.createElement("div");
    stale.className = "ck-stale";
    stale.textContent = "チェックのあとで文書が変わりました。「再チェック」で結果を新しくします";
    stale.hidden = !checkIsStale();
    parts.push(stale);

    const actions = document.createElement("div");
    actions.className = "sg-actions";
    const again = document.createElement("button");
    again.type = "button";
    again.className = "sg-btn ck-recheck";
    again.textContent = "再チェック";
    again.disabled = report.status === "checking";
    again.addEventListener("click", () => runDocumentCheck());
    actions.append(again);
    parts.push(actions);

    // 問題の一覧(ページごと。ページは目次の順、ページの中は本文の順)。確かめられなかった項目は別のまとまり。
    const group = (list, heading, kind) => {
      if (!list.length) return;
      const section = document.createElement("section");
      section.className = "ck-group ck-group-" + kind;
      const title = document.createElement("div");
      title.className = "ck-group-title";
      title.textContent = heading;
      section.append(title);
      const byPage = new Map();
      list.forEach((issue) => {
        if (!byPage.has(issue.pageId)) byPage.set(issue.pageId, []);
        byPage.get(issue.pageId).push(issue);
      });
      byPage.forEach((items) => {
        const page = document.createElement("div");
        page.className = "ck-page";
        const pageTitle = document.createElement("div");
        pageTitle.className = "ck-page-title";
        pageTitle.textContent = items[0].pageTitle;
        const count = document.createElement("span");
        count.className = "sg-count";
        count.textContent = items.length + " 件";
        pageTitle.append(" ", count);
        page.append(pageTitle);
        items.forEach((issue) => page.append(renderCheckItem(issue)));
        section.append(page);
      });
      parts.push(section);
    };
    group(report.issues, "問題", "issues");
    group(report.unchecked, "確かめられなかった項目", "unchecked");

    // 「問題なし」は正しさの保証ではない。何を調べ、何を調べていないかを書く。
    const note = document.createElement("p");
    note.className = "ck-note";
    note.textContent = "調べるのは、文書の中の参照・リンクの行き先、表の式のエラー、グラフ・図(Mermaid)・数式の誤りだけです。"
      + "書いた内容や計算の正しさは確かめていません。外部のリンク(URL)の行き先は確かめません(文書を外へ送りません)。"
      + "ゴミ箱のページは調べません。問題があっても、保存・配布はできます。";
    parts.push(note);
    checkPaneEl.replaceChildren(...parts);
    checkPaneEl.scrollTop = scroll;
  }

  function renderCheckItem(issue) {
    const item = document.createElement("button");
    item.type = "button";
    item.className = "ck-item";
    const key = checkIssueKey(issue);
    item.dataset.checkKey = key;
    item.dataset.category = issue.category;
    if (key === checkSelectedKey) item.setAttribute("aria-current", "true");
    const tag = document.createElement("span");
    tag.className = "ck-tag ck-tag-" + issue.category;
    tag.textContent = window.DocumentCheck.CATEGORY_LABELS[issue.category] || issue.category;
    const title = document.createElement("span");
    title.className = "ck-title";
    title.textContent = issue.title;
    const where = document.createElement("span");
    where.className = "ck-where";
    where.textContent = [issue.heading, issue.target].filter(Boolean).join(" › ");
    item.append(tag, title, where);
    if (issue.detail) {
      const detail = document.createElement("span");
      detail.className = "ck-detail";
      detail.textContent = issue.detail;
      item.append(detail);
    }
    if (issue.hint) {
      const hint = document.createElement("span");
      hint.className = "ck-hint";
      hint.textContent = issue.hint;
      item.append(hint);
    }
    item.title = "クリックでその場所へ移動";
    item.addEventListener("click", () => {
      checkSelectedKey = key;
      checkPaneEl.querySelectorAll(".ck-item[aria-current]").forEach((other) => other.removeAttribute("aria-current"));
      item.setAttribute("aria-current", "true");
      revealCheckIssue(issue);
    });
    return item;
  }

  // 項目を選ぶと、その場所へ移る(別のページなら切り替え、閉じたトグルの中なら開く。表のセルならそのセルを光らせる)。
  function revealCheckIssue(issue) {
    // 移るときに閉じたトグルを開くのは、チェックした中身の変更ではない(「チェックのあとで変わりました」にしない)。
    const fresh = checkEditSerial === editSerial;
    const row = goToBlock(issue.blockId, issue.pageId);
    if (fresh) {
      checkEditSerial = editSerial;
      syncCheckStale();
    }
    if (!row) {
      setStatus("その場所が見つかりません(チェックのあとで消したか移した)。再チェックしてください", "warn");
      return;
    }
    if (!issue.cell) return;
    const td = row.querySelector('.editor-table [data-row="' + issue.cell.row + '"][data-cell="' + issue.cell.col + '"]');
    if (!td) return;
    td.scrollIntoView({ block: "center", inline: "center" });
    flashRow(td, "ck-cell-flash");
  }

  // ---- 本文の上で決める: マウスを乗せた所(語句・セル・ブロック) ----
  function suggestLeafFromKey(key) {
    const [suggestionId, changeId, hunk] = String(key || "").split("|");
    const suggestion = suggestionList().find((item) => item.id === suggestionId);
    const change = suggestion?.changes.find((item) => item.id === changeId);
    if (!change) return null;
    return { suggestion, change, hunk: hunk === "" || hunk === undefined ? null : Number(hunk) };
  }

  function showSuggestPopup(target) {
    const leaf = suggestLeafFromKey(target.dataset.sgLeaf);
    if (!leaf) return;
    if (!suggestPopupEl) {
      suggestPopupEl = document.createElement("div");
      suggestPopupEl.className = "sg-popup";
      suggestPopupEl.addEventListener("mouseenter", () => clearTimeout(suggestPopupTimer));
      suggestPopupEl.addEventListener("mouseleave", () => scheduleHideSuggestPopup());
      document.body.append(suggestPopupEl);
    }
    clearTimeout(suggestPopupTimer);
    const what = leaf.change.op === "setCell" ? "このセル" : leaf.change.op === "setText" ? (leaf.hunk === null ? "この段落" : "この語句") : "このブロック";
    const label = document.createElement("span");
    label.textContent = what;
    const accept = document.createElement("button");
    accept.type = "button";
    accept.className = "sg-btn ok";
    accept.textContent = "採用";
    accept.addEventListener("click", () => { hideSuggestPopup(); decideSuggestionLeaves([leaf], "accepted"); });
    const reject = document.createElement("button");
    reject.type = "button";
    reject.className = "sg-btn ng";
    reject.textContent = "戻す";
    reject.addEventListener("click", () => { hideSuggestPopup(); decideSuggestionLeaves([leaf], "rejected"); });
    suggestPopupEl.replaceChildren(label, accept, reject);
    suggestPopupEl.hidden = false;
    const box = target.getBoundingClientRect();
    const top = box.top + window.scrollY - suggestPopupEl.offsetHeight - 6;
    suggestPopupEl.style.left = Math.max(8, box.left + window.scrollX) + "px";
    suggestPopupEl.style.top = (top < window.scrollY + 4 ? box.bottom + window.scrollY + 6 : top) + "px";
  }

  function scheduleHideSuggestPopup() {
    clearTimeout(suggestPopupTimer);
    suggestPopupTimer = setTimeout(hideSuggestPopup, 250);
  }

  function hideSuggestPopup() {
    clearTimeout(suggestPopupTimer);
    if (suggestPopupEl) suggestPopupEl.hidden = true;
  }

  blocksEl.addEventListener("mouseover", (event) => {
    const target = event.target.closest?.("[data-sg-leaf]");
    if (target && blocksEl.contains(target)) showSuggestPopup(target);
  });
  blocksEl.addEventListener("mouseout", (event) => {
    const target = event.target.closest?.("[data-sg-leaf]");
    if (target && !target.contains(event.relatedTarget)) scheduleHideSuggestPopup();
  });

  // ---- 本文の上で決める: 表の範囲を選んだとき ----
  function updateSuggestRangeBar(range) {
    suggestRangeBarEl?.remove();
    suggestRangeBarEl = null;
    if (range) withRenderMemo(() => showSuggestRangeBar(range));
  }

  function showSuggestRangeBar(range) {
    const { top, bottom, left, right } = tableRangeRect(range);
    const leaves = [];
    pendingSuggestions().forEach((suggestion) => suggestion.changes.forEach((change) => {
      if (change.op !== "setCell" || change.block !== range.blockId || change.result) return;
      if (change.row < top || change.row > bottom || change.col < left || change.col > right) return;
      if (suggestChangeState(suggestion, change).stale) return;
      leaves.push({ suggestion, change, hunk: null });
    }));
    if (!leaves.length) return;
    const corner = blocksEl.querySelector('.block[data-id="' + range.blockId + '"] .editor-table [data-row="' + bottom + '"][data-cell="' + left + '"]');
    if (!corner) return;
    suggestRangeBarEl = document.createElement("div");
    suggestRangeBarEl.className = "sg-range-bar";
    const label = document.createElement("span");
    label.textContent = "選んだ範囲の提案 " + leaves.length + " か所";
    const accept = document.createElement("button");
    accept.type = "button";
    accept.className = "sg-btn ok";
    accept.textContent = "採用";
    accept.addEventListener("pointerdown", (event) => event.preventDefault());
    accept.addEventListener("click", () => decideSuggestionLeaves(leaves, "accepted"));
    const reject = document.createElement("button");
    reject.type = "button";
    reject.className = "sg-btn ng";
    reject.textContent = "戻す";
    reject.addEventListener("pointerdown", (event) => event.preventDefault());
    reject.addEventListener("click", () => decideSuggestionLeaves(leaves, "rejected"));
    suggestRangeBarEl.append(label, accept, reject);
    document.body.append(suggestRangeBarEl);
    const box = corner.getBoundingClientRect();
    suggestRangeBarEl.style.left = (box.left + window.scrollX) + "px";
    suggestRangeBarEl.style.top = (box.bottom + window.scrollY + 8) + "px";
  }

  function afterRenderSuggestions() {
    renderSuggestPane();
    if (!pendingSuggestions().length) updateSuggestRangeBar(null);
  }

  // ---- 外での書き換えの取り込み(v245) ----
  // ユーザー案「AI は直接ファイルを編集する。開いていたら書き換わったことを検出して、その差分を今開いているドキュメントに表示し、
  // 受け入れるか無視するか、ブロック単位で承認する。受け入れなかったら元に戻す」。開いているファイル(PWA は開いたときの手がかり
  // fileHandle、デスクトップ版は場所 desktopPath)を見張り、外で書き換わったら読み直して:
  //   - 新しい提案(suggestions)は、そのまま提案として取り込む(同じ提案は、id が無くても中身で見分けて二重にしない)
  //   - 本文(pages)の書き換えは、前に読んだ・保存した中身(fileBaseline)との差分を、提案「ファイルの外の変更」にする。本文はまだ
  //     変えない。採用しなかった書き換えは、次に保存したときにファイルから消える(エディタの中身で書き直すので)
  // 保存の前にも見る。取り込んでいない書き換えがあれば先に取り込み、保存を止める(黙って上書きして消さない)。
  // 見るのは、窓に戻ったとき(focus)と、見えている間の一定の間隔。PWA は更新時刻だけを見て、変わったときだけ読む。デスクトップ版は
  // 今あるコマンド(read_linked_document。今の文書のフォルダからの相対パス)で同じファイルを読み、中身の要約(SHA-256)で比べる。
  let fileBaseline = null;
  let fileWatchRun = Promise.resolve(false);
  // 保存の途中(runSave が立てる。保存の前の確かめのほかは見ない)。
  let fileSaving = false;
  let fileUnreadableDigest = null;
  const FILE_WATCH_MS = 2000;

  function watchedFileSource() {
    return fileHandle || (desktop && desktopPath) || null;
  }

  // 提案の中身の目印(id・前の値・結果を除いたもの)。AI が id を付けずに書いた提案は、読むたびに id が振り直されるので、id では
  // 同じ提案かどうかを見分けられない。
  function suggestionSignature(suggestion) {
    const change = ({ id: changeId, before, result, hunkResults, insertedId, item, ...rest }) => {
      if (!item) return rest;
      const { id: itemId, ...body } = item;
      return { ...rest, item: body };
    };
    return stableJson([suggestion.author || null, suggestion.title || "", suggestion.reason || "", (suggestion.changes || []).map(change)]);
  }

  // キーの順番によらない JSON(外で書き換えた JSON はキーの順番が変わることがある)。
  function stableJson(value) {
    if (Array.isArray(value)) return "[" + value.map(stableJson).join(",") + "]";
    if (value && typeof value === "object") {
      return "{" + Object.keys(value).filter((key) => value[key] !== undefined).sort().map((key) => JSON.stringify(key) + ":" + stableJson(value[key])).join(",") + "}";
    }
    return JSON.stringify(value) ?? "null";
  }

  // ファイルの中身の控え(本文と提案の目印)。図の絵・表示用の写しは中身ではないので外す。
  function fileContentOf(value) {
    return {
      pages: JSON.parse(JSON.stringify((value.pages || []).map((page) => ({
        id: page.id,
        title: page.title,
        blocks: (page.blocks || []).map(({ mermaidSvg, chartSvg, derived, ...block }) => block),
      })))),
      signatures: (value.suggestions || []).map(suggestionSignature),
    };
  }

  async function textDigest(text) {
    if (globalThis.crypto?.subtle) {
      const bytes = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
      return [...new Uint8Array(bytes)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
    }
    let hash = 2166136261;
    for (let index = 0; index < text.length; index += 1) hash = Math.imul(hash ^ text.charCodeAt(index), 16777619);
    return text.length + ":" + (hash >>> 0).toString(16);
  }

  // 開いた・保存した時点のファイルを覚える(この後の外の書き換えは、これと比べる)。
  async function rememberWatchedFile(content, text, lastModified = null) {
    const source = watchedFileSource();
    fileBaseline = source ? { source, content, digest: await textDigest(text), lastModified } : null;
    fileUnreadableDigest = null;
  }

  async function readWatchedFile() {
    if (fileHandle && fileBaseline.source === fileHandle) {
      const file = await fileHandle.getFile();
      if (file.lastModified === fileBaseline.lastModified) return null;
      return { text: await file.text(), lastModified: file.lastModified };
    }
    if (desktop && desktopPath && fileBaseline.source === desktopPath) {
      // 先に目印(更新時刻と大きさ。document_stamp)だけを聞き、変わったときだけ全文を読む(v275。Issue #199。以前は 2 秒ごとに
      // 全文を読んで要約を取っていたので、動画の入った数十 MB の文書だとずっと重かった)。PWA の lastModified と同じ扱い。
      // 目印が取れない(古い exe など)ときは、今までどおり全文を読む。
      const stamp = await desktop.invoke("document_stamp", { path: desktopPath }).catch(() => null);
      const known = typeof stamp === "string" && stamp ? stamp : null;
      if (known && known === fileBaseline.lastModified) return null;
      const name = desktopPath.split(/[\\/]/).pop();
      const opened = await desktop.invoke("read_linked_document", { base: desktopPath, href: encodeURIComponent(name) });
      return { text: opened.contents, lastModified: known };
    }
    return null;
  }

  // 外の書き換えを見る。取り込んだら true。順番に1つずつ(見ている途中に次を始めない)。forSave は保存の前の確かめ。
  function checkWatchedFile(forSave = false) {
    const run = fileWatchRun.then(() => runWatchedFileCheck(forSave), () => runWatchedFileCheck(forSave));
    fileWatchRun = run.catch(() => false);
    return run;
  }

  async function runWatchedFileCheck(forSave) {
    if ((fileSaving && !forSave) || !fileBaseline || fileBaseline.source !== watchedFileSource()) return false;
    const baseline = fileBaseline;
    let read;
    try {
      read = await readWatchedFile();
    } catch {
      return false;
    }
    if (!read || fileBaseline !== baseline) return false;
    const digest = await textDigest(read.text);
    if (digest === baseline.digest) {
      baseline.lastModified = read.lastModified;
      return false;
    }
    if (digest === fileUnreadableDigest) return false;
    let external;
    try {
      external = fmt.parsePortableHtml(read.text);
    } catch {
      // 書いている途中・Monolio の文書でなくなった。同じ中身なら読み直さない(変わったら、もう一度読む)。
      fileUnreadableDigest = digest;
      return false;
    }
    if (fileBaseline !== baseline) return false;
    const content = fileContentOf(external);
    incorporateExternalDocument(external, content, baseline.content);
    fileBaseline = { ...baseline, content, digest, lastModified: read.lastModified };
    return true;
  }

  function incorporateExternalDocument(external, content, before) {
    // 1) 新しい提案: 前のファイルに無かった目印のもの(同じ目印が複数あれば、その数だけ前にあったとみなす)
    const known = new Map();
    before.signatures.forEach((signature) => known.set(signature, (known.get(signature) || 0) + 1));
    const incoming = [];
    (external.suggestions || []).forEach((suggestion, index) => {
      const signature = content.signatures[index];
      if (known.get(signature)) {
        known.set(signature, known.get(signature) - 1);
        return;
      }
      incoming.push(suggestion);
    });
    // 2) 本文の書き換え: 前のファイルとの差分を、提案の変更にする
    const { changes, notes } = externalContentChanges(before.pages, content.pages);
    if (!incoming.length && !changes.length) {
      if (notes.length) setStatus("ファイルが外で書き換わりました。" + notes.join("。") + "。", "warn", { sticky: true });
      return;
    }
    saveHistory();
    const taken = new Set(suggestionList().flatMap((suggestion) => [suggestion.id, ...suggestion.changes.map((change) => change.id)]));
    const unique = (value) => {
      const fresh = !value || taken.has(value) ? id() : value;
      taken.add(fresh);
      return fresh;
    };
    incoming.forEach((suggestion) => {
      suggestion.id = unique(suggestion.id);
      suggestion.changes.forEach((change) => { change.id = unique(change.id); });
    });
    // AI が前の値を書かなかった提案は、その提案が書かれたファイルの値を前とする(エディタで打った後なら「古い」になる)。
    const filePages = content.pages;
    const fileBlock = (blockId) => {
      for (const page of filePages) {
        const block = page.blocks.find((item) => item.id === blockId);
        if (block) return block;
      }
      return null;
    };
    incoming.forEach((suggestion) => suggestion.changes.forEach((change) => {
      if (change.before !== undefined || change.result) return;
      const block = change.block ? fileBlock(change.block) : null;
      if (change.op === "setText" && block) change.before = block.text || "";
      if (change.op === "setCell" && block) change.before = suggestCellObject(block, change.row, change.col)?.text || "";
    }));
    const added = [...incoming];
    if (changes.length) {
      added.push({
        id: unique(null),
        author: { name: "ファイルの外の変更", kind: "tool" },
        title: "ファイルが外で書き換えられた所",
        reason: "開いている間に、ファイルの本文が外で書き換えられました(AI・ほかのアプリなど)。採用しなかった書き換えは、保存するとファイルから消えます。",
        createdAt: new Date().toISOString(),
        changes: changes.map((change) => ({ ...change, id: unique(null) })),
      });
    }
    doc.suggestions = [...suggestionList(), ...added];
    // 足すブロックが使う添付は、外のファイルから持ってくる(保存の掃除でも、決めていない提案が使う添付は残る)。
    const have = new Set(doc.attachments.map((attachment) => attachment.id));
    const needed = new Set(added.flatMap((suggestion) => suggestion.changes)
      .filter((change) => change.op === "insertBlock").map((change) => change.item?.attachmentId).filter(Boolean));
    (external.attachments || []).forEach((attachment) => {
      if (needed.has(attachment.id) && !have.has(attachment.id)) doc.attachments.push(attachment);
    });
    suggestPaneOpen = true;
    render();
    if (changes.length) markDirty();
    const parts = [];
    if (incoming.length) parts.push("提案 " + incoming.length + " 件");
    if (changes.length) parts.push("本文の書き換え " + changes.length + " か所");
    setStatus("ファイルが外で書き換わりました。" + parts.join("と") + "を、提案として取り込みました"
      + (changes.length ? "(本文は採用するまで変わりません。採用しなかった書き換えは、保存するとファイルから消えます)" : "")
      + (notes.length ? "。" + notes.join("。") : ""), "warn", { sticky: true });
  }

  // 前のファイルの本文(beforePages)と外で書き換わった本文(afterPages)の差分を、提案の変更の並びにする。ブロックは id で対応させる。
  //   文字の変わったブロック → setText、表のセル → setCell、増えたブロック → insertBlock、消えたブロック → deleteBlock、
  //   そのほかが変わったブロック(種類・題名・表の形など) → 新しいブロックを足して元を消す(1つの提案の中で、2か所として決める)。
  // ページの増減・題名の変更・ブロックの並べ替えは、提案の変更で表せないので取り込まない(notes で知らせる)。
  function externalContentChanges(beforePages, afterPages) {
    const changes = [];
    const notes = [];
    const beforeBlocks = new Map();
    beforePages.forEach((page) => page.blocks.forEach((block) => beforeBlocks.set(block.id, block)));
    const afterIds = new Set();
    afterPages.forEach((page) => page.blocks.forEach((block) => afterIds.add(block.id)));
    const beforePageIds = new Set(beforePages.map((page) => page.id));
    const afterPageIds = new Set(afterPages.map((page) => page.id));
    const titleOf = new Map(beforePages.map((page) => [page.id, page.title]));
    if (afterPages.some((page) => !beforePageIds.has(page.id)) || beforePages.some((page) => !afterPageIds.has(page.id))
      || afterPages.some((page) => beforePageIds.has(page.id) && titleOf.get(page.id) !== page.title)) {
      notes.push("ページの追加・削除・題名の変更は取り込んでいません");
    }
    const strayItem = ({ columnGroup, columnIndex, columnWidth, ...block }) => JSON.parse(JSON.stringify(block));
    afterPages.forEach((page) => {
      if (!beforePageIds.has(page.id)) return;
      let anchor = null;
      page.blocks.forEach((block) => {
        const was = beforeBlocks.get(block.id);
        if (!was) {
          changes.push({ op: "insertBlock", after: anchor, page: page.id, item: strayItem(block) });
          return;
        }
        anchor = block.id;
        changes.push(...externalBlockChanges(was, block, page.id));
      });
      // 並べ替え: 両方にあるブロックの順番が違う
      const beforeOrder = (beforePages.find((item) => item.id === page.id)?.blocks || []).map((block) => block.id).filter((blockId) => afterIds.has(blockId));
      const afterOrder = page.blocks.map((block) => block.id).filter((blockId) => beforeBlocks.has(blockId));
      if (beforeOrder.join("\u0000") !== afterOrder.filter((blockId) => beforeOrder.includes(blockId)).join("\u0000")) {
        if (!notes.includes("ブロックの並べ替えは取り込んでいません")) notes.push("ブロックの並べ替えは取り込んでいません");
      }
    });
    beforePages.forEach((page) => {
      if (!afterPageIds.has(page.id)) return;
      page.blocks.forEach((block) => {
        if (!afterIds.has(block.id)) changes.push({ op: "deleteBlock", block: block.id });
      });
    });
    return { changes, notes };
  }

  // 1つのブロックの差分。
  function externalBlockChanges(was, block, pageId) {
    const replace = () => {
      const { columnGroup, columnIndex, columnWidth, ...item } = JSON.parse(JSON.stringify(block));
      return [{ op: "insertBlock", after: was.id, page: pageId, item: { ...item, id: id() } }, { op: "deleteBlock", block: was.id }];
    };
    if (was.type !== block.type) return replace();
    if (block.type === "table") {
      const { rows: wasRows, ...wasRest } = was;
      const { rows: nowRows, ...nowRest } = block;
      if (stableJson(wasRest) !== stableJson(nowRest)) return replace();
      const before = Array.isArray(wasRows) ? wasRows : [];
      const after = Array.isArray(nowRows) ? nowRows : [];
      const cellRest = (cell) => {
        const { text, colSpan, rowSpan, ...rest } = cell && typeof cell === "object" ? cell : { text: String(cell ?? "") };
        return stableJson({ ...rest, ...(colSpan > 1 ? { colSpan } : {}), ...(rowSpan > 1 ? { rowSpan } : {}) });
      };
      const cellText = (cell) => (cell && typeof cell === "object" ? cell.text ?? "" : String(cell ?? ""));
      const sameShape = before.length === after.length && before.every((row, index) => Array.isArray(row) && Array.isArray(after[index]) && row.length === after[index].length);
      if (!sameShape || before.some((row, r) => row.some((cell, c) => cellRest(cell) !== cellRest(after[r][c])))) return replace();
      const cells = [];
      before.forEach((row, r) => row.forEach((cell, c) => {
        if (cellText(cell) !== cellText(after[r][c])) cells.push({ op: "setCell", block: was.id, row: r, col: c, before: cellText(cell), text: cellText(after[r][c]) });
      }));
      return cells;
    }
    const { text: wasText, html: wasHtml, ...wasRest } = was;
    const { text: nowText, html: nowHtml, ...nowRest } = block;
    if (stableJson(wasRest) !== stableJson(nowRest)) return replace();
    if ((wasText || "") === (nowText || "") && (wasHtml || "") === (nowHtml || "")) return [];
    const change = { op: "setText", block: was.id, before: wasText || "", text: nowText || "" };
    // 書き換え後の html(書式)を持たせるかどうか: 語句の差分を前の html に当てた結果と同じなら要らない(語句ごとに決められる)。
    // html の文字が text と合わない(AI が text だけ直した)ときも持たせない(語句の差分を、今の書式に当てる)。
    if (nowHtml && suggestHtmlText(nowHtml) === change.text) {
      const formatted = /<(?!br\s*\/?>)[a-z]/i.test(nowHtml);
      let sameAsWords;
      if (suggestHasFormatting(was)) {
        sameAsWords = applyHunksToInlineHtml(wasHtml, change.before, suggestHunks(change.before, change.text), change.text) === sanitizeInlineHtml(nowHtml);
      } else sameAsWords = !formatted;
      if (!sameAsWords) change.html = nowHtml;
    }
    if (change.before === change.text && change.html === undefined) return [];
    return [change];
  }

  // 窓に戻ったときと、見えている間の一定の間隔で見る(読めない・取り込めないときは黙って次を待つ)。
  window.addEventListener("focus", () => { checkWatchedFile().catch(() => {}); });
  setInterval(() => {
    if (fileBaseline && document.visibilityState === "visible") checkWatchedFile().catch(() => {});
  }, FILE_WATCH_MS);

  function replaceDocument(next) {
    doc = next;
    // 前の文書で再生できなかった動画の覚えは捨てる(v273)。描き直しのたびには捨てない(捨てると、再生を試す→だめ→描き直す、を繰り返す)。
    unplayableVideos.clear();
    // 前の文書の埋め込みフォントを外す(#228。読めなかった覚えも捨てる。新しい文書のフォントは次の描き直しで登録する)。
    clearDocumentFonts();
    // 別の文書の行は使い回さない(同じファイルを開き直すと id が一致する。v225 の部分の描き直し)。
    fullRenderRequested = true;
    // 添付を画面に出す URL の控えも捨てる(Issue #218。描き直しのたびには捨てない。attachmentPreviewUrl の説明)。
    clearAttachmentPreviewUrls();
    // 本文の無いページ(blocks: [] の手書き・古いファイル)は、打てるブロックが1つも無く編集できなかった(v213)。
    // 開いたときに空の段落を1つ置く(ページを消して最後のブロックが無くなったときと同じ扱い)。保存形式の意味は変えない。
    doc.pages.forEach((page) => {
      if (!Array.isArray(page.blocks)) page.blocks = [];
      if (!page.blocks.length) page.blocks.push({ id: id(), type: "paragraph", text: "" });
    });
    currentPageId = doc.pages[0].id;
    // 提案(v240): 前の値の無い変更に今の値を入れ、選び・開閉の状態を新しい文書のために空にする。
    prepareSuggestions();
    lockBaselines.clear();
    ensureLockBaselines();
    // 前の文書の選択・アクティブなセル・表のセル範囲は、新しい文書の同じ id のブロックを指してしまうので捨てる
    // (同じファイルを開き直すと id が一致し、古い範囲が残っていた。v151)。
    leavePageUiState();
    tableCellRange = null;
    // 前の文書のページへ「戻る」ことはできないので、移動の履歴と位置の控えも捨てる。
    pageHistory.reset();
    pagePositions.clear();
    // 別の文書になったので、貼り付けの「同じ文書か」の判定と、外した添付の控えも切り替える。
    documentSessionId = id();
    // 文書チェックの結果は前の文書のもの(Issue #236)。
    resetDocumentCheck();
    detachedAttachments.clear();
    // コードを開いているグラフも、前の文書のもの(開き直した同じファイルは id が一致する)。
    openChartSources.clear();
    // Mermaid の図のコードの開閉も同じ(開いた文書の図は畳んで始める)。
    openMermaidSources.clear();
    // 検索の範囲も既定の「このページ」へ戻す(同じ文書の中ではセッションの間覚えておくが、別の文書へは持ち越さない)。
    searchScope = "page";
    if (searchScopeEl) searchScopeEl.value = "page";
  }

  // **題名は各ページが独立して持つ**(ユーザー指示)。画面上部の題名欄は今いるページの題名を編集し、
  // ほかのページの題名には触れない。**文書の題名という別の値は持たない**: 保存ファイルの <title> や
  // ファイル名など「文書の名前」が要る場面では、先頭ページの題名から導く(documentTitle)。
  // 値を2つ持って揃え続ける形(v131〜v133 の鏡合わせ)にすると、どこかで必ずずれる。
  function setCurrentPageTitle(text) {
    const page = currentPage();
    const before = pageTitleOf(page);
    page.title = text;
    followPageTitleInLinkCells(page.id, before, pageTitleOf(page));
  }

  // データベースのリンクのセルでこのページを指すもの(v267 #147)は、文字が元の題名のままなら新しい題名に合わせる
  // (ページのブロックが題名をその都度引くのと同じく、題名を変えればついてくる。文字を自分で変えたセルは触らない)。
  // 題名を打つ1手の中で変わるので、Undo も題名と一緒に戻る。ロック中のページのセルは書き換えない(安全網が戻すため)。
  function followPageTitleInLinkCells(pageId, before, after) {
    if (before === after) return;
    doc.pages.forEach((page) => {
      if (pageIsLocked(page)) return;
      const cells = pageLinkCellsIn(page, pageId).filter((cell) => cell.text === before);
      if (!cells.length) return;
      cells.forEach((cell) => { cell.text = after; });
      // 今のページの表は描き直す(セルの文字を読む式・グラフも。ほかのページは移ったときに描く)。
      if (page.id === currentPage().id) {
        page.blocks.filter((block) => block.type === "table" && pageLinkCellsIn({ blocks: [block] }, pageId).length)
          .forEach((block) => scheduleTableRecalc(block));
      }
    });
  }

  // 文書の名前 = 先頭ページの題名(保存時のファイル名に使う)。導出は document-format.js の1か所(P25)。
  function documentTitle() {
    return fmt.documentTitleOf(doc);
  }

  // **doc.pages への書き込みは、足すのがこの関数とゴミ箱から戻す restoreFromTrash()・取り除くのが deletePage() の3つだけ**(P25)。
  // 新しい入口(ページを複製する等)を足すときもここを通す。ページブロックを本文から消しても
  // ページの実体は消さない(P26。目次の「未分類」に出るだけ)。消すのは目次の「削除」だけ。
  function createPage(title) {
    const page = { id: id(), title: title || "Untitled", blocks: [{ id: id(), type: "paragraph", text: "" }] };
    doc.pages.push(page);
    return page;
  }

  function pageTitleOf(page) {
    return fmt.pageTitleOf(page);
  }

  // ---- ページの削除(Step 3) ----
  // **先頭ページは削除できない**(文書の入口。ユーザー確定)。判定はこの1関数だけにし、
  // **目次にメニューを出すかどうか**と**削除関数 deletePage() のガード**の両方がここを呼ぶ
  // (メニューだけだと別の入口から消せ、ガードだけだと押せるのに効かない項目が出る)。
  function canDeletePage(pageId) {
    return pageId !== doc.pages[0]?.id && doc.pages.some((page) => page.id === pageId);
  }

  // 削除すると先頭ページから辿れなくなり「未分類」へ移るページの数(子・孫。ほかの親から辿れるものは数えない)。
  // 確認ダイアログで先に見せる(P20)。もともと未分類にあったページは数えない。
  function countPagesMovedToUnclassified(pageId) {
    const childrenOf = fmt.pageChildrenMap(doc.pages);
    const before = fmt.pagesReachableFromFirst(doc.pages, childrenOf);
    const after = fmt.pagesReachableFromFirst(doc.pages, childrenOf, pageId);
    return [...before].filter((id) => id !== pageId && !after.has(id)).length;
  }

  // 削除で取り除かれる、**ほかのページ**にあるリンクの数(確認ダイアログで先に見せる。P20)。
  function countLinksToPageElsewhere(pageId) {
    return doc.pages
      .filter((page) => page.id !== pageId)
      .reduce((sum, page) => sum + page.blocks.filter((block) => block.type === "page" && block.pageId === pageId).length
        + pageLinkCellsIn(page, pageId).length, 0);
  }

  // ページ `page` の表で、`pageId` のページを行き先に持つセル(データベースのリンクの列。v267 #147)。ページへのリンクは
  // ページのブロックとこのセルの2種類で、削除で外す・数える・ロックで断るのどれもが両方を見る(片方だけだと、消したページを
  // 指すセルが残った)。読むだけなので、表の形を整える tableRows は通さない(ロック中のページの中身を変えない)。
  function pageLinkCellsIn(page, pageId) {
    const href = fmt.pageLinkHref(pageId);
    const cells = [];
    page.blocks.forEach((block) => {
      if (block.type !== "table" || !Array.isArray(block.rows)) return;
      block.rows.forEach((row) => (Array.isArray(row) ? row : []).forEach((cell) => {
        if (cell && typeof cell === "object" && typeof cell.link === "string" && cell.link.trim() === href) cells.push(cell);
      }));
    });
    return cells;
  }

  // `pageId` へのリンクを本文に持つ、**ロック中の**ほかのページ(v213)。削除するとそのリンクを取り除くことになるが、
  // ロック中のページは書き換えない(書き換えると安全網 enforcePageLocks が戻し、ロックしたページに行き先の無いリンクが残った)。
  // なので、こういうページがあるときは削除そのものを断る(ロックを解除してからにしてもらう)。部分的には変えない。
  function lockedPagesLinkingTo(pageId) {
    return doc.pages.filter((page) => page.id !== pageId && pageIsLocked(page)
      && (page.blocks.some((block) => block.type === "page" && block.pageId === pageId) || pageLinkCellsIn(page, pageId).length));
  }

  // 「ロック中のページ「A」「B」<reason>。そのページのロックを解除してから削除してください」と知らせる(v213)。
  function notifyLockedPagesBlockDelete(pages, reason) {
    setStatus("ロック中のページ「" + pages.map(pageTitleOf).join("」「") + "」" + reason
      + "。そのページのロックを解除してから削除してください", "warn");
  }

  // ページ `page` の本文から、`pageId` へのリンク(ページブロック)を取り除く。**全ページを書き換える
  // 唯一の入口**で、対象のページを引数に取る。removeBlock などの現在ページ専用の関数は使わない
  // (使うと、現在ページの別のブロックを消す)。**リンクの子ブロックは消さずに残す**
  // (removeBlockKeepingChildren と同じ規則。インデントを1つ戻す。P16)。
  // データベースのリンクのセル(v267 #147)は、文字(題名)を残して行き先だけ外す(ふつうの文字のセルになる)。
  function removePageLinksIn(page, pageId) {
    const blocks = page.blocks;
    pageLinkCellsIn(page, pageId).forEach((cell) => delete cell.link);
    let removed = 0;
    for (let index = blocks.length - 1; index >= 0; index -= 1) {
      if (blocks[index].type !== "page" || blocks[index].pageId !== pageId) continue;
      const count = subtreeRangeIn(blocks, index).count;
      for (let i = index + 1; i < index + count; i += 1) {
        blocks[i].indent = Math.max(0, (blocks[i].indent || 0) - 1);
      }
      blocks.splice(index, 1);
      removed += 1;
    }
    if (!removed) return 0;
    if (!blocks.length) blocks.push({ id: id(), type: "paragraph", text: "" });
    normalizeColumnLayouts(blocks);
    return removed;
  }

  // ページを削除する = **ゴミ箱へ移す**(Issue #187。あとで元に戻せる。完全に消すのはゴミ箱の「完全に削除」)。
  // **子ページは消さない**(連鎖削除しない。DESIGN_PRINCIPLES「削除は連鎖しない」)。先頭ページから辿れなくなった子は「未分類」に出て、
  // 元に戻すと、戻したページの本文にあるリンクで、また親の下へ戻る。
  // 削除したページへのリンクは**全ページから**取り除く(これまでどおり)。取り除いたリンクの場所はゴミ箱の項目に控え(links・cells)、
  // 元に戻すときにそこへ戻す。ページ・リンク・ゴミ箱を**Undo 1手**でまとめて戻す
  // (saveHistory は先頭で1回だけ。キャレット状態の pageId で、Undo は削除したときのページへ戻る)。
  function deletePage(pageId) {
    if (!canDeletePage(pageId)) return false;
    // ロック中のページにリンクが残るなら消さない(v213。画面の入口 requestDeletePage が先に知らせる。ここは関数側の守り)。
    if (lockedPagesLinkingTo(pageId).length) return false;
    saveHistory();
    const wasCurrent = currentPage().id === pageId;
    // **doc.pages から要素を取り除くのはここ1か所だけ**(P25。監査では grep で数える)。
    const index = doc.pages.findIndex((page) => page.id === pageId);
    const [page] = doc.pages.splice(index, 1);
    const links = [];
    const cells = [];
    doc.pages.forEach((other) => {
      other.blocks.forEach((block, at) => {
        if (block.type === "page" && block.pageId === pageId) {
          links.push({ pageId: other.id, afterId: other.blocks[at - 1]?.id ?? null, block: cloneDoc(block) });
        }
      });
      pageLinkCellPlacesIn(other, pageId).forEach((place) => cells.push({ pageId: other.id, ...place }));
      removePageLinksIn(other, pageId);
    });
    doc.trash = [...fmt.trashOf(doc), { id: id(), deletedAt: new Date().toISOString(), index, page, links, cells }];
    // ゴミ箱のページが使う添付は残る(allBlocks がゴミ箱も数える)。完全に削除したときに消える。
    removeUnusedAttachments();
    if (wasCurrent) {
      leavePageUiState();
      currentPageId = pageAfterDeletion(pageId);
    }
    render();
    if (wasCurrent) {
      focusBlock(currentBlocks()[0]?.id);
      window.scrollTo(0, 0);
    }
    markDirty();
    setStatus("「" + pageTitleOf(page) + "」をゴミ箱へ移しました(目次の下のゴミ箱から元に戻せます)", "ok", { notice: true });
    return true;
  }

  // ページ `page` の表で、`pageId` のページを行き先に持つセルの場所(ブロックの id と行・列)。ゴミ箱から戻すときに、そこへ行き先を戻す。
  function pageLinkCellPlacesIn(page, pageId) {
    const href = fmt.pageLinkHref(pageId);
    const places = [];
    page.blocks.forEach((block) => {
      if (block.type !== "table" || !Array.isArray(block.rows)) return;
      block.rows.forEach((row, rowIndex) => (Array.isArray(row) ? row : []).forEach((cell, colIndex) => {
        if (cell && typeof cell === "object" && typeof cell.link === "string" && cell.link.trim() === href) {
          places.push({ blockId: block.id, row: rowIndex, col: colIndex });
        }
      }));
    });
    return places;
  }

  // ---- ページのゴミ箱(Issue #187。形式 0.8.20) ----
  // 削除したページは doc.trash に入る(doc.pages には無い: 本文・目次・番号・検索・保存HTMLの表示には出ない)。ファイルには
  // 時計が無いので、**自分では空にならない**(Notion は 30 日で消えるが、ファイルを開くたびに日付で消えると、開いた日によって
  // 中身が変わる)。消えるのは「完全に削除」だけ。どちらの操作も Undo 1手。
  function trashEntry(entryId) {
    return fmt.trashOf(doc).find((entry) => entry.id === entryId) || null;
  }

  // 元に戻すと、外したリンクを戻すことになる、**ロック中の**ページ(戻せないので、元に戻すこと自体を断る。削除と同じ扱い)。
  function lockedPagesForRestore(entry) {
    const ids = new Set([...(entry.links || []), ...(entry.cells || [])].map((place) => place.pageId));
    return doc.pages.filter((page) => ids.has(page.id) && pageIsLocked(page));
  }

  // ゴミ箱のページを元に戻す。ページは削除したときの並びの位置へ、外したリンクは元の場所(直前のブロックの後ろ。そのブロックが
  // 無ければページの最後)へ戻す。リンクを戻す先のページが無くなっていれば戻さない(どこからもリンクされなければ「未分類」に出る)。
  // 戻したページの本文にある子ページへのリンクはそのままなので、未分類にいた子ページも親の下へ戻る。
  function restoreFromTrash(entryId) {
    const entry = trashEntry(entryId);
    if (!entry) return false;
    const lockedLinkers = lockedPagesForRestore(entry);
    if (lockedLinkers.length) {
      setStatus("ロック中のページ「" + lockedLinkers.map(pageTitleOf).join("」「") + "」にこのページへのリンクを戻すことになります。"
        + "そのページのロックを解除してから元に戻してください", "warn");
      return false;
    }
    saveHistory();
    doc.trash = fmt.trashOf(doc).filter((item) => item !== entry);
    if (!doc.trash.length) delete doc.trash;
    const page = entry.page;
    const usedBlockIds = new Set(doc.pages.flatMap((item) => item.blocks.map((block) => block.id)));
    // 同じ id のページ・ブロックが今の文書にあれば(ゴミ箱に入れたあとで同じ id のブロックを貼り付けた等)、戻す側を振り直す
    // (文書の中で id は重複しない。参照は今の文書の側を指したまま)。
    if (doc.pages.some((item) => item.id === page.id)) {
      const fresh = id();
      page.blocks.forEach((block) => { if (block.type === "page" && block.pageId === page.id) block.pageId = fresh; });
      entry.links.forEach((link) => { link.block.pageId = fresh; });
      page.id = fresh;
    }
    if (!Array.isArray(page.blocks)) page.blocks = [];
    page.blocks.forEach((block) => {
      if (usedBlockIds.has(block.id)) block.id = id();
      usedBlockIds.add(block.id);
    });
    if (!page.blocks.length) page.blocks.push({ id: id(), type: "paragraph", text: "" });
    doc.pages.splice(Math.max(1, Math.min(entry.index || doc.pages.length, doc.pages.length)), 0, page);
    const touched = new Set();
    (entry.links || []).forEach((link) => {
      const parent = doc.pages.find((item) => item.id === link.pageId && item !== page);
      if (!parent) return;
      const block = { ...link.block, pageId: page.id };
      if (usedBlockIds.has(block.id)) block.id = id();
      usedBlockIds.add(block.id);
      // 段組みの組が無くなっていれば、段組みの外へ戻す。
      if (block.columnGroup && !parent.blocks.some((item) => item.columnGroup === block.columnGroup)) clearColumnLayout(block);
      block.indent = fmt.clampIndent(block.indent || 0) || undefined;
      if (block.indent === undefined) delete block.indent;
      const at = link.afterId === null ? 0 : parent.blocks.findIndex((item) => item.id === link.afterId) + 1;
      parent.blocks.splice(link.afterId === null || at > 0 ? at : parent.blocks.length, 0, block);
      touched.add(parent);
    });
    const href = fmt.pageLinkHref(page.id);
    (entry.cells || []).forEach((place) => {
      const owner = doc.pages.find((item) => item.id === place.pageId)?.blocks.find((block) => block.id === place.blockId && block.type === "table");
      const cell = owner?.rows?.[place.row]?.[place.col];
      if (cell && typeof cell === "object" && !cell.link) cell.link = href;
    });
    touched.forEach((parent) => normalizeColumnLayouts(parent.blocks));
    // ロックしたまま削除したページは、ロックしたまま戻る。守る中身は戻した時点のもの。
    if (page.locked) rememberLockBaseline(page);
    removeUnusedAttachments();
    render();
    markDirty();
    setStatus("「" + pageTitleOf(page) + "」を元に戻しました", "ok", { notice: true });
    return true;
  }

  // ゴミ箱から完全に削除する(ページの中身と、そのページだけが使っていた添付が消える。Undo 1手で戻る)。
  // ゴミ箱のほかのページの本文にある、このページへのリンクも取り除く(元に戻したときに行き先の無いリンクが残らないように)。
  function purgeFromTrash(entryId) {
    const entry = trashEntry(entryId);
    if (!entry) return false;
    saveHistory();
    doc.trash = fmt.trashOf(doc).filter((item) => item !== entry);
    doc.trash.forEach((other) => removePageLinksIn(other.page, entry.page.id));
    if (!doc.trash.length) delete doc.trash;
    removeUnusedAttachments();
    render();
    markDirty();
    setStatus("「" + pageTitleOf(entry.page) + "」を完全に削除しました", "ok", { notice: true });
    return true;
  }

  async function requestPurgeFromTrash(entryId) {
    const entry = trashEntry(entryId);
    if (!entry) return false;
    if (!(await confirmAction("「" + pageTitleOf(entry.page) + "」を完全に削除しますか(ゴミ箱からも消え、元に戻せなくなります)"))) return false;
    return purgeFromTrash(entryId);
  }

  // 画面を通さずに削除関数を直接呼ぶ入口(テスト・監査用)。先頭ページのガードがメニュー側だけでなく
  // **関数の側にもある**ことを確かめるために使う。文書を変える経路は deletePage() そのもので、別の抜け道ではない。
  // ゴミ箱(Issue #187)とブロックの移動(Issue #193)も、画面と同じ関数を呼ぶだけ。
  window.__docEditorPages = Object.freeze({
    deletePage: (pageId) => deletePage(pageId),
    restoreFromTrash: (entryId) => restoreFromTrash(entryId),
    purgeFromTrash: (entryId) => purgeFromTrash(entryId),
    moveBlocksToPage: (blockIds, pageId) => moveBlocksToPage(blockIds, pageId),
    // 読むだけ(写しを返す。添付の中身は除く)。
    documentCopy: () => JSON.parse(JSON.stringify({ ...doc, attachments: doc.attachments.map(({ chunks, ...rest }) => rest) })),
  });

  // 現在ページを削除したときの移り先: 移動の履歴で1つ前にある、存在するページ。無ければ先頭ページ。
  // **「戻る」と同じ扱い**: 位置だけ前へ動かし、列は切り詰めない。削除したページの項目は**進む側に残り**、
  // 削除中は辿るときに飛ばされ、Undo でページが戻れば「進む」でまた行ける。「新しい移動」として
  // 進む側を捨てると、Undo で戻したページへ進むで辿れなくなる(TL の指摘)。
  function pageAfterDeletion(deletedId) {
    return pageHistory.stepBackFrom(deletedId, (pageId) => doc.pages.some((page) => page.id === pageId))
      || doc.pages[0].id;
  }

  // 目次のメニューの「削除」から来る。確認のうえで deletePage() を呼ぶ(キャンセルなら何も変えない)。
  async function requestDeletePage(pageId) {
    closePageMenu();
    if (!canDeletePage(pageId)) return false;
    if (pageIsLocked(doc.pages.find((page) => page.id === pageId))) {
      notifyPageLocked();
      return false;
    }
    const lockedLinkers = lockedPagesLinkingTo(pageId);
    if (lockedLinkers.length) {
      notifyLockedPagesBlockDelete(lockedLinkers, "にこのページへのリンクがあります");
      return false;
    }
    const links = countLinksToPageElsewhere(pageId);
    // **事前に見せる内容は事実どおりに**(P20): 未分類へ移るのは、ほかの親から先頭ページへ辿れない子(と孫)だけ。
    // 移るページが無ければ前半を、取り除くリンクが無ければ後半を省く。
    const moved = countPagesMovedToUnclassified(pageId);
    const notes = [];
    if (moved) notes.push("子ページ " + moved + " 件は未分類に移ります");
    if (links) notes.push("他のページの " + links + " 箇所のリンクも取り除かれます");
    const message = "このページを削除しますか" + (notes.length ? "(" + notes.join("。") + ")" : "");
    if (!(await confirmAction(message))) return false;
    return deletePage(pageId);
  }

  // ---- 目次のページのメニュー(ページ名の横の ⋯ / 右クリック) ----
  // 見た目は ＋・スラッシュ・ハンドルのメニューと同じ .popover / .menu-item(P20)。
  let pageMenuReturnFocus = null;

  function openPageMenu(pageId, anchor) {
    if (!pageMenuEl || !canDeletePage(pageId)) return;
    closeBlockMenu();
    closeSlashMenu();
    const remove = menuButton({ icon: ic("trash"), title: "削除", desc: "ゴミ箱へ移します(元に戻せます)。子ページは残ります" }, () => requestDeletePage(pageId));
    remove.type = "button";
    remove.dataset.action = "delete-page";
    remove.setAttribute("role", "menuitem");
    remove.classList.add("active");
    const page = doc.pages.find((item) => item.id === pageId);
    const lock = menuButton(page?.locked
      ? { icon: ic("lock-open"), title: "ロック解除", desc: "このページを編集できるようにします" }
      : { icon: ic("lock"), title: "ロック", desc: "ロックを外すまで、このページを編集できなくします" }, () => {
      closePageMenu();
      setPageLocked(pageId, !page?.locked);
    });
    lock.type = "button";
    lock.dataset.action = "toggle-page-lock";
    lock.setAttribute("role", "menuitem");
    pageMenuEl.classList.remove("is-trash");
    pageMenuEl.setAttribute("aria-label", "ページの操作");
    pageMenuEl.replaceChildren(remove, lock);
    pageMenuEl.dataset.pageId = pageId;
    pageMenuEl.hidden = false;
    pageMenuReturnFocus = anchor;
    positionMenuNearAnchor(pageMenuEl, anchor);
    remove.focus();
  }

  function closePageMenu() {
    if (!pageMenuEl || pageMenuEl.hidden) return;
    pageMenuEl.hidden = true;
    pageMenuEl.replaceChildren();
    delete pageMenuEl.dataset.pageId;
    pageMenuEl.classList.remove("is-trash");
    pageMenuEl.setAttribute("aria-label", "ページの操作");
  }

  function closePageMenuFromPointer(event) {
    if (!pageMenuEl || pageMenuEl.hidden || pageMenuEl.contains(event.target)) return;
    closePageMenu();
  }

  // ---- 被リンク(Issue #188。Notion の「バックリンク」) ----
  // ほかのページから今のページを指しているもの: 文中のページへのリンク(@)・ページのブロック・表のセルのページへのリンク・
  // このページのブロックを指すブロックへのリンクと表・図・見出しの参照。同じページの中からのものは数えない(Notion と同じ)。
  // 数は描き直しのたびに数える(印の行き先は syncFigureRefTexts の控えを読むので、文書全体を読み直さない)。今のページを
  // 見ている間に、ほかのページのリンクは変わらない(変えるにはそのページへ移る=描き直す)ので、打鍵では数え直さない。
  const backlinksButton = document.querySelector("#page-backlinks");
  const backlinksCount = document.querySelector("#page-backlinks-count");
  const backlinksMenu = document.querySelector("#backlinks-menu");
  const BACKLINK_KIND_LABELS = {
    mention: "ページへのリンク", "page-block": "ページのブロック", "cell-link": "表のセルのリンク",
    "block-link": "ブロックへのリンク", reference: "参照",
  };

  function pageBacklinks(target = currentPage()) {
    if (!target) return [];
    const ownBlocks = new Set((target.blocks || []).map((block) => block.id));
    const href = fmt.pageLinkHref(target.id);
    // 「参照先なし」の印(題名を外した表への参照など)は数えない。行き先は描き直しの控えがあればそれを使う(#205)。
    let targets = renderMemo?.targets || null;
    const resolves = (ref, kind) => Boolean(fmt.resolveReference(targets ||= fmt.referenceTargets(doc), ref, kind));
    const found = [];
    doc.pages.forEach((page) => {
      if (page.id === target.id) return;
      (page.blocks || []).forEach((block) => {
        const kinds = new Set();
        if (block.type === "page" && block.pageId === target.id) kinds.add("page-block");
        figureRefsOf(block).forEach(([ref, kind]) => {
          if (ref !== target.id && !ownBlocks.has(ref)) return;
          if (!resolves(ref, kind)) return;
          if (ref === target.id && !ownBlocks.has(ref)) kinds.add("mention");
          else kinds.add(kind === fmt.REF_KIND_BLOCK ? "block-link" : "reference");
        });
        if (block.type === "table" && Array.isArray(block.rows)
          && block.rows.some((row) => Array.isArray(row) && row.some((cell) => cell && typeof cell === "object" && typeof cell.link === "string" && cell.link.trim() === href))) {
          kinds.add("cell-link");
        }
        kinds.forEach((kind) => found.push({ page, block, kind }));
      });
    });
    return found;
  }

  function renderBacklinksButton() {
    if (!backlinksButton) return;
    const count = doc.pages.length > 1 ? pageBacklinks().length : 0;
    if (!count) closeBacklinksMenu();
    backlinksButton.hidden = !count;
    if (backlinksCount.textContent !== String(count || "")) backlinksCount.textContent = count ? String(count) : "";
    const label = "このページへのリンク(被リンク) " + count + " 件。押すと一覧";
    backlinksButton.title = label;
    backlinksButton.setAttribute("aria-label", label);
  }

  function openBacklinksMenu() {
    if (!backlinksMenu) return;
    closeBlockMenu();
    closeSlashMenu();
    closePageMenu();
    const links = pageBacklinks();
    const section = document.createElement("div");
    section.className = "menu-section";
    section.setAttribute("role", "presentation");
    section.textContent = "このページへのリンク";
    // リンクのある所の文字(印の文字も含めた本文。長ければ詰める)。表・ページのブロックは種類だけ。
    const excerpt = (block) => {
      const chars = [...String(block.text || "").replaceAll("​", "").replace(/\s+/g, " ").trim()];
      if (block.type === "table" || !chars.length) return "";
      return "「" + (chars.length > 40 ? chars.slice(0, 40).join("").trimEnd() + "…" : chars.join("")) + "」";
    };
    const buttons = links.map(({ page, block, kind }) => {
      const where = kind === "page-block" ? "" : excerpt(block);
      const button = menuButton({ icon: ic("page"), title: pageTitleOf(page), desc: BACKLINK_KIND_LABELS[kind] + (where ? ": " + where : "") }, () => {
        closeBacklinksMenu();
        jumpToFigure(block.id);
      });
      button.type = "button";
      button.dataset.action = "backlink";
      button.dataset.page = page.id;
      button.dataset.block = block.id;
      button.dataset.kind = kind;
      button.setAttribute("role", "menuitem");
      return button;
    });
    backlinksMenu.replaceChildren(section, ...buttons);
    backlinksMenu.hidden = false;
    backlinksButton.setAttribute("aria-expanded", "true");
    positionMenuNearAnchor(backlinksMenu, backlinksButton);
    buttons[0]?.focus();
  }

  function closeBacklinksMenu() {
    if (!backlinksMenu || backlinksMenu.hidden) return;
    backlinksMenu.hidden = true;
    backlinksMenu.replaceChildren();
    backlinksButton?.setAttribute("aria-expanded", "false");
  }

  backlinksButton?.addEventListener("click", () => {
    if (backlinksMenu.hidden) openBacklinksMenu();
    else closeBacklinksMenu();
  });
  backlinksMenu?.addEventListener("keydown", (event) => {
    const items = [...backlinksMenu.querySelectorAll(".menu-item")];
    const at = items.indexOf(document.activeElement);
    if (event.key === "Escape") {
      event.preventDefault();
      closeBacklinksMenu();
      backlinksButton.focus();
    } else if ((event.key === "ArrowDown" || event.key === "ArrowUp") && items.length) {
      event.preventDefault();
      items[(at + (event.key === "ArrowDown" ? 1 : -1) + items.length) % items.length].focus();
    }
  });

  // ページを切り替える。**履歴に積まない・dirty にしない**(どのページを見ているかは UI 状態)。
  // ---- ページの戻る/進む(ブラウザの戻る/進むと同じ) ----
  // 移動の履歴は **UI 状態**: doc にも保存ファイルにも入れず、Undo の履歴とも別に持つ。
  // 戻る/進むは dirty にせず、Undo の履歴も増やさない。新規作成・ファイルを開いたときは
  // replaceDocument() が空にする。**Undo で別ページへ切り替わったときは積まない**(Undo は編集の
  // 巻き戻しであって移動ではない。積むと「戻る」が Undo 前の場所へ飛び、2つの履歴が絡む)。
  // 操作は**画面のボタン2つだけ**(ユーザー指示)。キーやマウスの戻るボタン・popstate は扱わない
  // (扱わなければ、ブラウザ自身の戻る操作とぶつからない)。
  // 履歴は**1本の列と今の位置**で持つ(ブラウザの履歴と同じ形)。**無くなったページの項目は
  // 取り除かず、辿るときに飛ばす**(Step 3)。削除のときに取り除くと、Undo でページが戻っても
  // 履歴は戻らず、そのページへ二度と「戻る」で行けなくなる。
  // 本体は document-format.js の createPageHistory(保存HTMLの戻る/進むも同じ関数を使う。P25)。
  const pageHistory = fmt.createPageHistory((pageId) => isReachablePage(pageId));
  // ページごとに最後にいた位置(スクロールとキャレット)。戻る/進むで来たときにそこへ戻す。
  const pagePositions = new Map();

  // ページを移る(目次・ページリンク・/page で作成して移る)。**移動の履歴に積む**。
  // 戻った状態で別のページへ移ったら、進む側の履歴は捨てる(ブラウザと同じ)。
  function switchToPage(pageId, { keepSearchRoot = false } = {}) {
    const from = currentPage().id;
    if (!showPage(pageId, { keepSearchRoot })) return false;
    pageHistory.visit(from, pageId);
    renderPageNav();
    return true;
  }

  function goBackPage() {
    return goToPageHistoryEntry(pageHistory.reachable(-1));
  }

  function goForwardPage() {
    return goToPageHistoryEntry(pageHistory.reachable(1));
  }

  function goToPageHistoryEntry(index) {
    if (index < 0) return false;
    showPage(pageHistory.moveTo(index), { restorePosition: true });
    renderPageNav();
    return true;
  }

  // 辿れるページ: 存在して、今いるページでない(無くなったページ = 削除・ページ作成の Undo は飛ばす)。
  function isReachablePage(pageId) {
    return pageId !== currentPage().id && doc.pages.some((page) => page.id === pageId);
  }

  // ページの場所(v207。ユーザー選択の案B: メニューの下の1行)。「親 › 自分」で、親の親があれば「… › 親 › 自分」
  // (ユーザー指示「階層全部ではなく、自分と親だけ」)。「…」は省いた上の階層を名前で示し(乗せると出る)、押すと親の親へ。
  // 親の道は保存HTMLと同じ(fmt.pageAncestors)。1ページの文書では出さない。題名の上の親のページ名(v201)はこれに置き換えた。
  function renderPagePath() {
    if (!pagePathEl) return;
    const multiPage = doc.pages.length > 1;
    pagePathEl.hidden = !multiPage;
    if (!multiPage) {
      pagePathEl.replaceChildren();
      return;
    }
    const titleOf = (id) => pageTitleOf(doc.pages.find((item) => item.id === id));
    const ancestors = fmt.pageAncestors(doc.pages, currentPage().id).filter((id) => doc.pages.some((item) => item.id === id));
    const parts = [];
    const sep = () => {
      const span = document.createElement("span");
      span.className = "page-path-sep";
      span.setAttribute("aria-hidden", "true");
      span.textContent = "›";
      return span;
    };
    const link = (id, text, title) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "page-path-item";
      button.dataset.pageId = id;
      button.textContent = text;
      button.title = title;
      button.addEventListener("click", () => switchToPage(id));
      return button;
    };
    if (ancestors.length > 1) {
      const hidden = ancestors.slice(0, -1);
      parts.push(link(hidden.at(-1), "…", hidden.map(titleOf).join(" › ")), sep());
    }
    if (ancestors.length) parts.push(link(ancestors.at(-1), titleOf(ancestors.at(-1)), titleOf(ancestors.at(-1))), sep());
    const self = document.createElement("span");
    self.className = "page-path-current";
    self.setAttribute("aria-current", "page");
    self.textContent = pageTitleOf(currentPage());
    self.title = self.textContent;
    parts.push(self);
    pagePathEl.replaceChildren(...parts);
  }

  function renderPageNav() {
    if (pageBackEl) pageBackEl.disabled = pageHistory.reachable(-1) < 0;
    if (pageForwardEl) pageForwardEl.disabled = pageHistory.reachable(1) < 0;
  }

  function rememberPagePosition() {
    pagePositions.set(currentPage().id, { scrollY: window.scrollY, anchor: topVisibleBlockAnchor(), caret: captureCaretState() });
  }

  // 画面のいちばん上に見えているブロックと、その上端の位置(v252。Issue #104)。戻るときはスクロールの量ではなく、このブロックを
  // 同じ位置へ合わせる(上に高さの決まっていない画像があると、量で戻すと読み込みのあとでずれていた)。
  function topVisibleBlockAnchor() {
    const row = [...blocksEl.querySelectorAll(".block[data-id]")].find((node) => node.getBoundingClientRect().bottom > 0);
    return row ? { blockId: row.dataset.id, top: row.getBoundingClientRect().top } : null;
  }

  function scrollToAnchor(anchor) {
    const row = anchor && blocksEl.querySelector('.block[data-id="' + anchor.blockId + '"]');
    if (!row) return false;
    window.scrollTo(0, Math.max(0, window.scrollY + row.getBoundingClientRect().top - anchor.top));
    return true;
  }

  // 位置を合わせたあと、画像の読み込みで高さが変わったら合わせ直す。使う人が自分で動かしたら(ホイール・タッチ・キー・クリック)やめる
  // (ブラウザのスクロールの追従が動かした分は合わせ直す。追従は高さの変わった画像の近くを基準にしてずれることがある)。
  function keepAnchorWhileImagesLoad(anchor) {
    const pending = [...blocksEl.querySelectorAll("img")].filter((image) => !image.complete);
    if (!anchor || !pending.length) return;
    let userMoved = false;
    const pageId = currentPage().id;
    const stop = () => { userMoved = true; };
    ["wheel", "touchmove", "keydown", "pointerdown"].forEach((type) => window.addEventListener(type, stop, { once: true, passive: true, capture: true }));
    const settle = () => {
      if (userMoved || currentPage().id !== pageId) return;
      scrollToAnchor(anchor);
    };
    pending.forEach((image) => {
      image.addEventListener("load", settle, { once: true });
      image.addEventListener("error", settle, { once: true });
    });
  }

  // 選択やアクティブなセル・開いているメニューは前のページのブロックを指しているので捨てる。
  function leavePageUiState() {
    closeBlockMenu();
    closeSlashMenu();
    closePageMenu();
    selectedBlockId = null;
    selectedBlockIds = [];
    activeBlockId = null;
    activeEditable = null;
    activeTableCell = null;
    // 選んでいるグラフも前のページ(前の文書)のもの。開き直した同じファイルは id が一致するので、
    // 実在の確認だけでは閉じない。ここで必ず閉じる(v157)。
    closeChartPane();
  }

  // ページを表示する(履歴には積まない)。戻る/進むでは、そのページで最後にいた位置へ戻す。
  function showPage(pageId, { restorePosition = false, keepSearchRoot = false } = {}) {
    if (!doc.pages.some((page) => page.id === pageId) || pageId === currentPage().id) return false;
    rememberPagePosition();
    leavePageUiState();
    // 入力のまとめ(coalesce)はここで切らなくてよい。まとめのキーはブロック id を含み
    // ("input:" + blockId …)、別ページのブロックとは決して一致しないので、ページを跨いで
    // 一手に合流することは構造上起きない。
    currentPageId = pageId;
    // 検索中に**自分で**ページを移ったら、そのページを起点・基準に検索し直す(一致の位置は新しいページから)。
    // 検索の「次へ」でページをまたいだときは keepSearchRoot で起点も位置も保つ。
    if (searchState && !keepSearchRoot) {
      searchRootPageId = pageId;
      searchState.index = -1;
    }
    render();
    const saved = restorePosition ? pagePositions.get(pageId) : null;
    if (saved) {
      // キャレットを戻してから、スクロールを最後に見ていた位置へ(フォーカスでずれるので後から合わせる)。
      restoreCaretState(saved.caret);
      if (!scrollToAnchor(saved.anchor)) window.scrollTo(0, saved.scrollY);
      keepAnchorWhileImagesLoad(saved.anchor);
    } else {
      focusBlock(currentBlocks()[0]?.id);
      window.scrollTo(0, 0);
    }
    closePageTreeOverlay();
    return true;
  }

  function currentBlocks() {
    return currentPage().blocks;
  }

  // 配列を丸ごと差し替えるときだけ使う(filter の結果を戻す、など)。
  function setCurrentBlocks(next) {
    currentPage().blocks = next;
  }

  // 返すのは連結した**新しい配列**なので、push/splice しても文書には反映されない。
  // 黙って捨てられると原因が分からなくなるため、凍らせて例外で気づけるようにする。
  // **ゴミ箱のページ(Issue #187。doc.trash)も含める**。ここを使うのは「見落とすとデータが消える」処理(添付の掃除・書体の収集)
  // なので、元に戻せるページが使う添付・書体を消してはいけない(含めないと、ページを削除して保存しただけで、元に戻したページの画像が消える)。
  function allBlocks() {
    return Object.freeze([...doc.pages, ...trashPages()].flatMap((page) => page.blocks || []));
  }

  // ゴミ箱のページ(元に戻せる)。本文・目次・検索・番号は見ない(doc.pages ではない)。
  function trashPages() {
    return fmt.trashOf(doc).map((entry) => entry.page).filter(Boolean);
  }
  let numberedMarkers = new Map();
